INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with bl, br, cl and ch', ARRAY['ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T1_FLUENCY.a']::text[], 'The child hears and picks out words with bl, br, cl and the sound /tʃ/ (ch) in a sentence or short oral text (for example blue, brush, clap, chair) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 3, 'Say words that begin with two or three consonants together', ARRAY['ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.e', 'ENGL.G3.READIN.T15_FLUENCY.b']::text[], 'The child says words that start with a consonant blend (bl, br, cl, dr, fl, fr, gl, cr, pl, st, sn, pr, sm, sw, sp, thr, gr, shr, spl, spr, str, scr) as one beat, with no vowel slipped between the consonants and no consonant dropped. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the word list aloud","say the sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO', 'english', 3, 'Know and choose the new words of the theme', ARRAY['ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.b', 'ENGL.G3.READIN.T2_COMPREHENSION.a', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING.a']::text[], 'The child chooses the theme word that fits a sentence or a picture (for example sweep, duties, greet, rights, nurse, phone, helmet, calf, giraffe, drum, race, germs, save, talent, litter) and does not swap it for a word of the same group. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the word that fits","match the word to the picture","fill the gap"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY', 'ENGL.G3.READIN.T1_FLUENCY', 'english', 3, 'Read a Grade 3 text aloud accurately and at the right speed', ARRAY['ENGL.G3.READIN.T1_FLUENCY.b', 'ENGL.G3.READIN.T3_FLUENCY.b', 'ENGL.G3.READIN.T4_FLUENCY.b', 'ENGL.G3.READIN.T5_FLUENCY.b', 'ENGL.G3.READIN.T7_FLUENCY.b', 'ENGL.G3.READIN.T8_FLUENCY.c', 'ENGL.G3.READIN.T9_FLUENCY.b', 'ENGL.G3.READIN.T11_FLUENCY.b', 'ENGL.G3.READIN.T12_FLUENCY.b', 'ENGL.G3.READIN.T13_FLUENCY.b', 'ENGL.G3.READIN.T15_FLUENCY.c']::text[], 'The child reads a short Grade 3 text aloud with almost every word right, sounding out unfamiliar words with the letter-sound combinations learnt instead of guessing, at a steady speed (about 60 to 80 words a minute is a guide, to confirm by the teacher). Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","read a page of a graded reader","timed reading of a short passage"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.PREDICT', 'ENGL.G3.READIN.T1_COMPREHENSION', 'english', 3, 'Predict what will happen in a story from the title, pictures and clues', ARRAY['ENGL.G3.READIN.T1_COMPREHENSION.a', 'ENGL.G3.READIN.T2_COMPREHENSION.b', 'ENGL.G3.READIN.T4_COMPREHENSION.a', 'ENGL.G3.READIN.T5_COMPREHENSION.b', 'ENGL.G3.READIN.T6_COMPREHENSION.a', 'ENGL.G3.READIN.T7_COMPREHENSION.b', 'ENGL.G3.READIN.T8_COMPREHENSION.b', 'ENGL.G3.READIN.T9_COMPREHENSION.a', 'ENGL.G3.READIN.T10_COMPREHENSION.a', 'ENGL.G3.READIN.T11_COMPREHENSION.a', 'ENGL.G3.READIN.T12_COMPREHENSION.a', 'ENGL.G3.READIN.T13_COMPREHENSION.a', 'ENGL.G3.READIN.T14_COMPREHENSION.a', 'ENGL.G3.READIN.T15_COMPREHENSION.a']::text[], 'The child uses the title, the pictures and what has happened so far to say what is likely to happen next, gives the clue for the guess, and checks the guess as the story goes on. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what will happen next","which title clue helps","choose the best prediction"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING', 'ENGL.G3.READIN.T1_COMPREHENSION', 'english', 3, 'Name the characters and the setting of a story', ARRAY['ENGL.G3.READIN.T1_COMPREHENSION.b', 'ENGL.G3.READIN.T5_COMPREHENSION.a']::text[], 'The child names the people or animals in a story (Hare, Grandmother, Otieno) and its setting, where and when it happens (at the market, on a rainy morning). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["who is in the story","where and when does it happen","which one is a character"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'ENGL.G3.READIN.T1_COMPREHENSION', 'english', 3, 'Work out the meaning of a new word from the words and pictures around it', ARRAY['ENGL.G3.READIN.T1_COMPREHENSION.c', 'ENGL.G3.READIN.T2_COMPREHENSION.c', 'ENGL.G3.READIN.T5_COMPREHENSION.c', 'ENGL.G3.READIN.T11_COMPREHENSION.b', 'ENGL.G3.READIN.T12_COMPREHENSION.c', 'ENGL.G3.READIN.T14_COMPREHENSION.c', 'ENGL.G3.READIN.T15_COMPREHENSION.c']::text[], 'The child reads the sentence before and after a new word, uses the picture, and chooses the meaning that fits this sentence, even for a word with more than one meaning. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what does the word mean here","which word could replace it","which clue helps"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'ENGL.G3.READIN.T1_COMPREHENSION', 'english', 3, 'Answer questions whose answers are stated in the text', ARRAY['ENGL.G3.READIN.T1_COMPREHENSION.d', 'ENGL.G3.READIN.T4_COMPREHENSION.b', 'ENGL.G3.READIN.T5_COMPREHENSION.d', 'ENGL.G3.READIN.T6_COMPREHENSION.b', 'ENGL.G3.READIN.T7_COMPREHENSION.c', 'ENGL.G3.READIN.T8_COMPREHENSION.c', 'ENGL.G3.READIN.T9_COMPREHENSION.b', 'ENGL.G3.READIN.T11_COMPREHENSION.c', 'ENGL.G3.READIN.T12_COMPREHENSION.d', 'ENGL.G3.READIN.T13_COMPREHENSION.b', 'ENGL.G3.READIN.T14_COMPREHENSION.d', 'ENGL.G3.READIN.T15_COMPREHENSION.d']::text[], 'The child finds the sentence that answers who, what, where and when, and answers from the text, not from home life, with the kind of answer the question word asks for. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["answer the question on the text","choose the best answer","which sentence tells you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME', 'english', 3, 'Use am, is, are, was and were to agree with the subject', ARRAY['ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.a', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.b']::text[], 'The child picks am, is, are, was or were from a text and uses the one that agrees with the subject and the time: I am, she is, they are, I was, we were. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_', 'english', 3, 'Know which letters are tall (ascenders) and which hang below the line (descenders)', ARRAY['ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.a']::text[], 'The child knows that b, d, f, h, k, l and t reach up (t a little less), that g, j, p, q and y hang below the line, and spots a word where they are written the wrong size. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letters are tall","which letter goes below the line","which word is written right"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_', 'english', 3, 'Write words clearly and legibly in print', ARRAY['ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.b', 'ENGL.G3.WRITIN.T2_HANDWRITING.b', 'ENGL.G3.WRITIN.T3_HANDWRITING.b', 'ENGL.G3.WRITIN.T4_HANDWRITING.b', 'ENGL.G3.WRITIN.T5_HAND_WRITING.b', 'ENGL.G3.WRITIN.T6_SPELLING.b', 'ENGL.G3.WRITIN.T8_SPELLING.b', 'ENGL.G3.WRITIN.T7_SPELLING.c']::text[], 'The child writes print letters of the right shape and size, starting each letter at the right point, with tall letters tall, tails below the line and no capitals inside words, so that anyone can read it. Evidence rule: the teacher sees it in two pieces of the learner''s own work, scored with the KICD rubric indicator.', '["copy the words neatly","write the theme words","write the sentence on the lines"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with dr, fl, fr and gl', ARRAY['ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T2_FLUENCY.a']::text[], 'The child hears and picks out words with dr, fl, fr and gl in a sentence or short oral text (for example drum, flag, frog, glass) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO', 'english', 3, 'Listen to and carry out a three-step spoken instruction', ARRAY['ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.c']::text[], 'The child listens to a three-step instruction said once (Pick up the red book, put it on the table and sit down) and does all three steps in the order given. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["do what the teacher says","Simon says with three steps","draw what you hear"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION', 'ENGL.G3.READIN.T2_FLUENCY', 'english', 3, 'Read aloud with expression: pausing at full stops and changing the voice for questions and speech', ARRAY['ENGL.G3.READIN.T2_FLUENCY.b', 'ENGL.G3.READIN.T6_FLUENCY.b', 'ENGL.G3.READIN.T10_FLUENCY.b', 'ENGL.G3.READIN.T14_FLUENCY.b']::text[], 'The child pauses at full stops and commas, lifts the voice for a yes or no question, sounds excited at an exclamation mark and changes the voice for what a character says. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read a dialogue in parts","read a sentence as a question and as a statement","read with feeling"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'ENGL.G3.READIN.T2_COMPREHENSION', 'english', 3, 'Answer questions whose answers are not stated but shown by clues', ARRAY['ENGL.G3.READIN.T2_COMPREHENSION.d', 'ENGL.G3.READIN.T1_COMPREHENSION.d', 'ENGL.G3.READIN.T4_COMPREHENSION.b', 'ENGL.G3.READIN.T5_COMPREHENSION.d', 'ENGL.G3.READIN.T6_COMPREHENSION.b', 'ENGL.G3.READIN.T7_COMPREHENSION.c', 'ENGL.G3.READIN.T8_COMPREHENSION.c', 'ENGL.G3.READIN.T9_COMPREHENSION.b', 'ENGL.G3.READIN.T11_COMPREHENSION.c', 'ENGL.G3.READIN.T12_COMPREHENSION.d', 'ENGL.G3.READIN.T13_COMPREHENSION.b', 'ENGL.G3.READIN.T14_COMPREHENSION.d', 'ENGL.G3.READIN.T15_COMPREHENSION.d']::text[], 'The child answers why and how questions by joining clues in the text (She sat alone and cried: she was sad) and can point to the clue, without making up what the clues do not show. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["why do you think","how did the character feel","what clue tells you"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO', 'english', 3, 'Use do, does and did to agree with the subject', ARRAY['ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.a', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.b']::text[], 'The child picks do, does and did from a text and uses does with he, she and it, do with I, you, we and they, and did for the past, with a plain verb after it: Did you wash? She does her duties. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING', 'ENGL.G3.WRITIN.T2_HANDWRITING', 'english', 3, 'Leave a finger space between words and none inside a word', ARRAY['ENGL.G3.WRITIN.T2_HANDWRITING.a', 'ENGL.G3.WRITIN.T5_HAND_WRITING.a']::text[], 'The child leaves a finger space between words, no space inside a word, and spots writing where words run together or are split. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which sentence is spaced right","where should the space go","how many words"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with cr, pl, st and sn', ARRAY['ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T3_FLUENCY.a']::text[], 'The child hears and picks out words with cr, pl, st and sn in a sentence or short oral text (for example crab, plate, stone, snake) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA', 'ENGL.G3.READIN.T3_COMPREHENSION', 'english', 3, 'Say what a text is mainly about and why it was written', ARRAY['ENGL.G3.READIN.T3_COMPREHENSION.a', 'ENGL.G3.READIN.T7_COMPREHENSION.a', 'ENGL.G3.READIN.T14_COMPREHENSION.b']::text[], 'The child chooses the idea the whole text is about (how to keep the classroom clean), not one detail and not something too wide (school), and says whether the text tells a story, gives facts or tells us how to do something. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the text mainly about","choose the best title","why was it written"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE', 'ENGL.G3.READIN.T3_COMPREHENSION', 'english', 3, 'Summarise a short text in two or three sentences', ARRAY['ENGL.G3.READIN.T3_COMPREHENSION.b', 'ENGL.G3.READIN.T11_COMPREHENSION.d', 'ENGL.G3.READIN.T13_COMPREHENSION.c']::text[], 'The child gives the main happenings in order in two or three short sentences, leaving out small details and his or her own opinion. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the best summary","which sentence should be in the summary","say it in three sentences"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS', 'ENGL.G3.READIN.T3_COMPREHENSION', 'english', 3, 'Put the events of a text in the order they happened', ARRAY['ENGL.G3.READIN.T3_COMPREHENSION.c', 'ENGL.G3.READIN.T8_COMPREHENSION.a', 'ENGL.G3.READIN.T12_COMPREHENSION.b', 'ENGL.G3.READIN.T15_COMPREHENSION.b']::text[], 'The child puts three to five events in the order they happened, using first, then, after that and finally, and reads before and after correctly even when the text tells them out of order. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what happened first","put the sentences in order","what happened after"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME', 'english', 3, 'Use have, has and had to agree with the subject', ARRAY['ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.a', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.b']::text[], 'The child picks have, has and had from a text and uses has with he, she and it, have with I, you, we and they, and had for the past: She has a pencil. We had lunch. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE', 'ENGL.G3.WRITIN.T3_HANDWRITING', 'english', 3, 'Sit letters on the line and keep to the margin', ARRAY['ENGL.G3.WRITIN.T3_HANDWRITING.a']::text[], 'The child sits every letter on the line, lets only the tails of g, j, p, q and y go below it, keeps lines straight and starts at the margin. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which writing sits on the line","which letters go below the line","spot the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with wr, pr, sm and st', ARRAY['ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T4_FLUENCY.a']::text[], 'The child hears and picks out words with wr (said /r/), pr, sm and st in a sentence or short oral text (for example write, pray, smile, stand) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS', 'english', 3, 'Use nobody, anybody and somebody in sentences', ARRAY['ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.a', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.b']::text[], 'The child finds nobody, anybody and somebody in a text and uses them correctly: somebody in statements, anybody in questions and after not, nobody with a positive verb (Nobody came), each with a singular verb. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q', 'ENGL.G3.WRITIN.T4_HANDWRITING', 'english', 3, 'Write b, d, p and q the right way round', ARRAY['ENGL.G3.WRITIN.T4_HANDWRITING.a']::text[], 'The child writes and chooses b, d, p and q the right way round (bed, dog, pig, queen) and does not turn words round (was, saw). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which letter is right","fix the word","which word is written right"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with sl, st, sw, sp and thr', ARRAY['ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T5_FLUENCY.a']::text[], 'The child hears and picks out words with sl, st, sw, sp and thr in a sentence or short oral text (for example sleep, stick, sweep, spoon, three) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT', 'ENGL.G3.READIN.T5_COMPREHENSION', 'english', 3, 'Tell others about a text read, in his or her own words', ARRAY['ENGL.G3.READIN.T5_COMPREHENSION.e']::text[], 'The child tells a partner about a story or text read: the title, who was in it, what happened in order and how it ended, in full sentences and own words. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["tell a friend about the story","retell the story","what was your book about"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS', 'english', 3, 'Use the singular and plural of irregular nouns', ARRAY['ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.a', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.b']::text[], 'The child finds irregular nouns in a text and uses the right singular and plural: child and children, man and men, woman and women, foot and feet, tooth and teeth, mouse and mice, sheep and sheep. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with dr, gr and shr', ARRAY['ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T6_FLUENCY.a']::text[], 'The child hears and picks out words with dr, gr and shr in a sentence or short oral text (for example drive, grass, shrub) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI', 'english', 3, 'Talk about the future with will and shall', ARRAY['ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.a', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.b']::text[], 'The child picks words that show future time (tomorrow, next week, will, shall) and uses will or shall with a plain verb: I shall call you. She will use the computer tomorrow. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR', 'ENGL.G3.WRITIN.T6_SPELLING', 'english', 3, 'Spell words with dr, gr and shr', ARRAY['ENGL.G3.WRITIN.T6_SPELLING.a']::text[], 'The child spells theme words with dr, gr and shr (drive, grass, shrub, shrink) with both consonants and no extra vowel. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with dw, tw, nk and sq', ARRAY['ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T7_FLUENCY.a']::text[], 'The child hears and picks out words with dw, tw, nk and sq (said /skw/) in a sentence or short oral text (for example dwell, twins, bank, square) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS', 'english', 3, 'Join ideas with but and because', ARRAY['ENGL.G3.LANGUA.T7_CONJUNCTIONS.a', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.b', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.c']::text[], 'The child finds but and because in a text and joins two ideas with them: but for ideas that pull different ways (I was tired but I finished), because to give a reason (I wore a helmet because it keeps me safe). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["join the two sentences","choose but or because","complete the sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ', 'ENGL.G3.WRITIN.T7_SPELLING', 'english', 3, 'Spell words with dw, tw, nk and squ', ARRAY['ENGL.G3.WRITIN.T7_SPELLING.a']::text[], 'The child spells words with dw, tw, nk and squ (dwell, twins, bank, square), always writing u after q. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES', 'ENGL.G3.WRITIN.T7_SPELLING', 'english', 3, 'Write simple sentences about the theme', ARRAY['ENGL.G3.WRITIN.T7_SPELLING.b']::text[], 'The child writes two to four complete sentences about the theme, each with a capital letter, a verb and a full stop, using theme words spelt correctly. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write two sentences about","write a sentence with the word","finish the sentence"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words that end in ft, ct, lt and rd', ARRAY['ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T8_FLUENCY.a']::text[], 'The child hears and picks out words with the endings -ft, -ct, -lt and -rd in a sentence or short oral text (for example gift, insect, belt, bird) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO', 'english', 3, 'Say words that end in two or three consonants together', ARRAY['ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.b', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.b']::text[], 'The child says words that end in a consonant blend (-ft, -ct, -lt, -rd, -lk, -lf, -lm, -mp, -mb, -nt, -nd, -nch, -pt, -nth) with every sounded consonant heard, no vowel added at the end, and silent letters (lamb, walk, half) kept silent. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say the word after the teacher","read the word list aloud","say the sentence"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT', 'ENGL.G3.READIN.T8_FLUENCY', 'english', 3, 'Notice and fix a word misread while reading aloud', ARRAY['ENGL.G3.READIN.T8_FLUENCY.b']::text[], 'The child notices when a word read does not make sense or does not match the letters (house read as horse), goes back, sounds it out and reads the sentence again, without waiting to be told. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["read aloud to the teacher","does that make sense","read again and fix"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS', 'ENGL.G3.LANGUA.T8_QUANTIFIERS', 'english', 3, 'Use some, many, much, a few and a lot of correctly', ARRAY['ENGL.G3.LANGUA.T8_QUANTIFIERS.a', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.b', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.c']::text[], 'The child finds quantifiers in a text and uses many and a few with things we count (many cows) and much with things we do not count (much milk), and a lot of and some with both. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD', 'ENGL.G3.WRITIN.T8_SPELLING', 'english', 3, 'Spell words that end in ft, ct, lt and rd', ARRAY['ENGL.G3.WRITIN.T8_SPELLING.a']::text[], 'The child spells words ending in -ft, -ct, -lt and -rd (gift, insect, belt, bird) with both final consonants and no vowel added at the end. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct spelling","fill in the missing letters","spot the wrong spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words that end in lk, lf, lm and mp', ARRAY['ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T9_FLUENCY.a']::text[], 'The child hears and picks out words with the endings -lk, -lf, -lm and -mp in a sentence or short oral text (for example milk, shelf, film, lamp) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE', 'ENGL.G3.READIN.T9_COMPREHENSION', 'english', 3, 'Picture characters, places and events from the words of a text', ARRAY['ENGL.G3.READIN.T9_COMPREHENSION.c', 'ENGL.G3.READIN.T10_COMPREHENSION.b']::text[], 'The child uses all the describing words in a text to picture a character, place or event (a tall thin man in a red hat on a dusty road at night) and chooses or draws the picture that matches every detail. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which picture matches the text","draw what the text says","what would you see"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES', 'ENGL.G3.LANGUA.T9_OPPOSITES', 'english', 3, 'Give and use the opposites of words', ARRAY['ENGL.G3.LANGUA.T9_OPPOSITES.a', 'ENGL.G3.LANGUA.T9_OPPOSITES.b']::text[], 'The child gives the opposite of common words (big and small, fast and slow, wild and tame, old and young, old and new) and uses both in sentences about wild animals. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what is the opposite","fill the gap with the opposite","match the pairs"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM', 'english', 3, 'Use commas to separate items in a list', ARRAY['ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.a', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.b']::text[], 'The child finds commas in a text and writes a list with a comma between items and and before the last one, with no comma before and (British style, teacher to confirm): lions, zebras, giraffes and elephants. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put in the commas","which sentence is punctuated right","write the list"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words that end in mb, nt, nd and nch', ARRAY['ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T10_FLUENCY.a']::text[], 'The child hears and picks out words with the endings -mb (b silent), -nt, -nd and -nch in a sentence or short oral text (for example thumb, tent, hand, lunch) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'ENGL.G3.LANGUA.T10_PREPOSITIONS', 'english', 3, 'Use prepositions to say where things are and where they go', ARRAY['ENGL.G3.LANGUA.T10_PREPOSITIONS.a', 'ENGL.G3.LANGUA.T10_PREPOSITIONS.b']::text[], 'The child finds the target prepositions in a text and uses them to describe position, place and direction: on, in, under, behind, in front of, between, above, across, towards. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["where is it","choose the preposition","describe the picture"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS', 'ENGL.G3.WRITIN.T10_PUNCTUATION', 'english', 3, 'Use capital letters for sentence starts, names and I', ARRAY['ENGL.G3.WRITIN.T10_PUNCTUATION.a', 'ENGL.G3.WRITIN.T10_PUNCTUATION.b']::text[], 'The child starts every sentence with a capital, writes capitals for names of people, places, days and festivals (Juma, Mombasa, Monday, Christmas, Eid) and for I, and nowhere else. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word needs a capital","correct the sentence","choose the right sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS', 'ENGL.G3.WRITIN.T10_PUNCTUATION', 'english', 3, 'End sentences with a full stop, question mark or exclamation mark', ARRAY['ENGL.G3.WRITIN.T10_PUNCTUATION.a', 'ENGL.G3.WRITIN.T10_PUNCTUATION.b']::text[], 'The child ends a statement with a full stop, a question with a question mark and a strong feeling with an exclamation mark, and puts the mark at the end of the sentence, not the end of the line. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which mark goes at the end","correct the sentence","choose the right sentence"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with nkl, pt, nth and nd', ARRAY['ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T11_FLUENCY.a']::text[], 'The child hears and picks out words with -nkl-, -pt, -nth and -nd in a sentence or short oral text (for example ankle, kept, tenth, pond) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI', 'english', 3, 'Compare with -er and -est', ARRAY['ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.a', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.b', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.c']::text[], 'The child finds -er and -est adjectives in a text and uses -er with than to compare two (Ali is taller than Ben) and the -est with the to compare three or more (the tallest in the class), spelling big, bigger and happy, happier right. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING', 'english', 3, 'Name and write the objects in pictures', ARRAY['ENGL.G3.WRITIN.T11_GUIDED_WRITING.a', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING.b']::text[], 'The child names the objects in theme pictures (ball, net, whistle, skipping rope) in English and writes each name spelt correctly, one word for one picture. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the picture","write the word for the picture","choose the correct spelling"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with gr, pr and ew', ARRAY['ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T12_FLUENCY.a']::text[], 'The child hears and picks out words with gr-, pr- and -ew (said /juː/ or /uː/) in a sentence or short oral text (for example grain, price, new, grew) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_', 'english', 3, 'Use mine, yours, his, hers, ours and theirs', ARRAY['ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.a', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.b']::text[], 'The child finds possessive pronouns in a text and uses them instead of a noun (The book is mine), his for a boy and hers for a girl, with no apostrophe. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA', 'ENGL.G3.WRITIN.T12_PARAGRAPHS', 'english', 3, 'Find the general idea in jumbled sentences', ARRAY['ENGL.G3.WRITIN.T12_PARAGRAPHS.a']::text[], 'The child reads four or five jumbled sentences, says what they are all about, and spots a sentence that does not belong. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["what are the sentences about","choose a title","which sentence does not belong"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES', 'ENGL.G3.WRITIN.T12_PARAGRAPHS', 'english', 3, 'Put jumbled sentences in order to make a paragraph', ARRAY['ENGL.G3.WRITIN.T12_PARAGRAPHS.b']::text[], 'The child orders jumbled sentences into a paragraph using time words (first, then, finally), the name before he or she, and the problem before the answer, and writes them one after another. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the sentences in order","which sentence comes first","what comes next"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and tell apart words with lf, rf and spl', ARRAY['ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T13_FLUENCY.a']::text[], 'The child hears and picks out words with -lf, -rf and spl- in a sentence or short oral text (for example shelf, scarf, splash) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS', 'english', 3, 'Ask questions with why, whom and how', ARRAY['ENGL.G3.LANGUA.T13_WH_QUESTIONS.a', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.b', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.c']::text[], 'The child finds questions starting with why, whom and how in a text and asks them in the right order with a question mark: Why are you late? How did you save the money? Whom did you call? Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the question word","write the question","put the words in order"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING', 'english', 3, 'Write a simple paragraph on the theme', ARRAY['ENGL.G3.WRITIN.T13_GUIDED_WRITING.b']::text[], 'The child writes a paragraph of four to six sentences on one idea, one sentence after another on the line (not one per line), joined in more ways than and then. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a paragraph about","write four sentences on one idea","add a sentence to the paragraph"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with spr and str', ARRAY['ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T14_FLUENCY.a']::text[], 'The child hears and picks out words with spr and str in a sentence or short oral text (for example spray, spring, street, string) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER', 'english', 3, 'Use adverbs of manner to describe how something is done', ARRAY['ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.a', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.b', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.c']::text[], 'The child finds adverbs of manner in a text and uses them to tell how an action is done: She sang beautifully. He ran quickly. Most end in -ly; well goes with good. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["choose the correct word","fill the gap","spot and correct the mistake"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING', 'english', 3, 'Know the steps of writing: plan, draft, revise, edit and publish', ARRAY['ENGL.G3.WRITIN.T14_GUIDED_WRITING.a']::text[], 'The child names the five steps in order (planning, drafting, revising, editing, publishing) and says what happens at each: revising changes ideas, editing fixes spelling and punctuation. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the steps in order","what do we do at this step","which step comes next"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING', 'english', 3, 'Write a short story following the steps of writing', ARRAY['ENGL.G3.WRITIN.T14_GUIDED_WRITING.b']::text[], 'The child plans, drafts, revises, edits and publishes a short story of about 50 words in the past tense with characters, a setting, a problem and an ending. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a story about","plan and write a story","finish the story"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO', 'english', 3, 'Hear and pick out words with scr and qu', ARRAY['ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.a', 'ENGL.G3.READIN.T15_FLUENCY.a']::text[], 'The child hears and picks out words with scr- and qu(e) (said /kw/, or /kjuː/ in queue) in a sentence or short oral text (for example scrub, screen, queen, question, queue) and tells them from words that differ by one sound. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word has the sound","circle the words with the sound","odd one out by sound"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO', 'english', 3, 'Use new words in spoken sentences and short conversations', ARRAY['ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.c', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.d', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.d']::text[], 'The child uses new theme words in full spoken sentences in a short conversation, in the right meaning (lend and borrow, switch on, not open the light), and adds a little more than a one-word answer. Evidence rule: the teacher hears it done right on two different days, scored with the observation rubric (PLAN_OBSERVATION_RUBRICS.md); a tapped answer cannot show it.', '["say a sentence with the word","talk with a partner using the words","answer and say more"]'::jsonb, '["performance"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS', 'english', 3, 'Use words that show displeasure', ARRAY['ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.a', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.b']::text[], 'The child picks interjections that show displeasure (Ugh! Oh no! Yuck! Alas!) and uses the right one for the feeling, followed by an exclamation mark, in polite language. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["which word shows how the person feels","choose the right word","complete with an interjection"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU', 'english', 3, 'Tell facts from opinions and story sentences', ARRAY['ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.a']::text[], 'The child picks sentences that can be checked as true (Trees give us shade) and tells them from opinions (Trees are beautiful) and story sentences (One day a tree spoke). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["fact or opinion","which sentence is a fact","find the facts"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU', 'english', 3, 'Order facts about a process logically', ARRAY['ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.b']::text[], 'The child orders the facts of a process (planting a tree: dig a hole, put in the seedling, cover the roots, water it) so each step can happen, and spots a missing step. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the steps in order","what comes before","which step is missing"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU', 'english', 3, 'Write a paragraph of facts', ARRAY['ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.c']::text[], 'The child writes a paragraph that opens with what it is about, gives facts in a sensible order with first, next and finally, and keeps out story and opinion. Evidence rule: two pieces of the learner''s own writing marked Meeting Expectations or above on the KICD rubric indicator.', '["write a paragraph of facts about","write the steps as a paragraph","tell how to"]'::jsonb, '["creation","organisation"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.BL_SP_SC_SK_CK', 'skill', 'essential', 'Grade 2 told apart words with bl, sp, sc, sk and ck. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.CH_OA_SH_CL', 'skill', 'essential', 'Grade 2 recognised /tʃ/ and /kl/. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'skill', 'essential', 'Hearing the blend comes before saying it. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'ENGL.G2.LISTEN.T2_PRONUNCIATION_AND_VO.SAY_CONSONANT_SOUNDS', 'skill', 'essential', 'Grade 2 articulated target letter-sound combinations. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'ENGL.G2.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'skill', 'essential', 'Grade 2 used theme vocabulary. Proposed, to confirm by a Kenyan English teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
