INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH.M3_BL_BR_SWAP', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'Hears bl and br as the same sound.', '{"question":"Which word starts with bl: blue, brown, clap?","wrong_answer":"brown","correct_answer":"blue"}'::jsonb, 'Several Kenyan home languages do not keep /l/ and /r/ apart, so bl and br sound alike.', 'Offer "brown" beside "blue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Watch the tongue: up behind the teeth for l, curled back for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH.M3_BL_FIRST_LETTER', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'Picks any word that starts with the first letter of the blend.', '{"question":"Which word starts with bl: bag, black, cup?","wrong_answer":"bag","correct_answer":"black"}'::jsonb, 'The child listens for the first letter only, not the two sounds together.', 'Offer "bag" beside "black" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it slowly: b-l-ack. Bag has b, then a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH.M3_CH_SH', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'Hears ch (/tʃ/) as sh (/ʃ/).', '{"question":"Which word starts with the sound in chair: shop, chin, sun?","wrong_answer":"shop","correct_answer":"chin"}'::jsonb, 'A home language with sh and no ch (or the reverse) carries over.', 'Offer "shop" beside "chin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ch starts with a stop, like a sneeze: t-sh, chin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH.M3_CL_TWO_BEATS', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.BLENDS_BL_BR_CL_CH', 'Hears a vowel between the two consonants and claps two beats.', '{"question":"Clap the beats in \"clap\".","wrong_answer":"2 (ku-lap)","correct_answer":"1"}'::jsonb, 'Bantu languages build syllables that end in a vowel, so a vowel is heard in English clusters.', 'Offer "2 (ku-lap)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'C and l are glued together: one clap, clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS.M3_PSB_EXTRA_VOWEL', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'Slips a vowel between the consonants of a blend.', '{"question":"Say: blue","wrong_answer":"bulu","correct_answer":"blue"}'::jsonb, 'Bantu languages build syllables that end in a vowel.', 'Offer "bulu" beside "blue" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Glue the two consonants: b-l, blue, one beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS.M3_PSB_L_R', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'Says l for r, or r for l, in a blend.', '{"question":"Say: The frog can fly.","wrong_answer":"The flog can fry.","correct_answer":"The frog can fly."}'::jsonb, 'L and r are one sound in some home languages.', 'Offer "The flog can fry." beside "The frog can fly." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l, curled back for r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS.M3_PSB_DROP', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'Drops one consonant of the blend.', '{"question":"Say: stop","wrong_answer":"top","correct_answer":"stop"}'::jsonb, 'Two consonants together feel hard, so one is left out.', 'Offer "top" beside "stop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with the hiss, then t: sss-top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS.M3_PSB_TH_T', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.PRONOUNCE_START_BLENDS', 'Says thr as tr.', '{"question":"Say: three","wrong_answer":"tree","correct_answer":"three"}'::jsonb, 'Th is missing in most Kenyan home languages.', 'Offer "tree" beside "three" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue between the teeth, blow, then r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M3_TW_COOKER', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Uses a thing word for a person word.', '{"question":"A person who cooks food in a hotel is a ...","wrong_answer":"cooker","correct_answer":"cook"}'::jsonb, 'Common Kenyan English: cooker is the stove, not the person.', 'Offer "cooker" beside "cook" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A cook is a person; a cooker is the stove.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M3_TW_SAME_GROUP', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word from the same group but not the right one.', '{"question":"The animal that gives us wool is a ...","wrong_answer":"goat","correct_answer":"sheep"}'::jsonb, 'The child knows the group (farm animals) but not the exact word.', 'Offer "goat" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Think about what makes this one different: wool comes from sheep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M3_TW_SOUND_ALIKE', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Picks a word that sounds like the right one.', '{"question":"We wear a ... on our head when riding a bicycle.","wrong_answer":"hammer","correct_answer":"helmet"}'::jsonb, 'The child matches the sound of the word, not its meaning.', 'Offer "hammer" beside "helmet" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say the sentence with the word: does it make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS.M3_TW_PICTURE_NEAR', 'ENGL.G3.LISTEN.T1_PRONUNCIATION_AND_VO.THEME_WORDS', 'Names something next to the object in the picture.', '{"question":"Picture: a girl holding a broom. What is she holding?","wrong_answer":"floor","correct_answer":"broom"}'::jsonb, 'The child names what stands out in the picture, not what was asked.', 'Offer "floor" beside "broom" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point at the thing in her hand, then name it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY.M3_RA_GUESS_FIRST', 'ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY', 'Guesses a word from its first letter or the picture.', '{"question":"Read: The cow is in the house.","wrong_answer":"The cow is in the horse.","correct_answer":"The cow is in the house."}'::jsonb, 'Sight-word guessing: the child has learnt to guess from the first letter and the picture instead of reading every letter.', 'Offer "The cow is in the horse." beside "The cow is in the house." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at every letter, left to right: h-ou-se.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY.M3_RA_B_D', 'ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY', 'Reads b as d or d as b.', '{"question":"Read: The bed is big.","wrong_answer":"The deb is dig.","correct_answer":"The bed is big."}'::jsonb, 'B and d are the same shape turned round, and young readers often still mix them.', 'Offer "The deb is dig." beside "The bed is big." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists: b first (left), d last (right).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY.M3_RA_SKIP_SMALL', 'ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY', 'Skips small words such as the, a and of.', '{"question":"Read: A cup of tea is on the table.","wrong_answer":"Cup tea is on table.","correct_answer":"A cup of tea is on the table."}'::jsonb, 'Small words carry little meaning for the child and the eye jumps to the big ones.', 'Offer "Cup tea is on table." beside "A cup of tea is on the table." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point under every word as you read it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY.M3_RA_WORD_BY_WORD', 'ENGL.G3.READIN.T1_FLUENCY.READ_ACCURATELY', 'Reads word by word with a stop after each word.', '{"question":"Read: Wanjiru sweeps the classroom every morning.","wrong_answer":"Wanjiru. Sweeps. The. Classroom. Every. Morning.","correct_answer":"Wanjiru sweeps the classroom / every morning."}'::jsonb, 'Each word is decoded on its own and not yet joined into phrases.', 'Offer "Wanjiru. Sweeps. The. Classroom. Every. Morning." beside "Wanjiru sweeps the classroom / every morning." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it once in your head, then read it in two scoops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.PREDICT.M3_PR_DESCRIBES', 'ENGL.G3.READIN.T1_COMPREHENSION.PREDICT', 'Describes the picture instead of predicting.', '{"question":"Title: The Lost Calf. Picture: a boy looking behind a bush. What will happen?","wrong_answer":"There is a boy and a bush.","correct_answer":"The boy will find the calf behind the bush."}'::jsonb, 'The child answers what is seen, not what will happen.', 'Offer "There is a boy and a bush." beside "The boy will find the calf behind the bush." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what will happen next? Use will.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.PREDICT.M3_PR_NO_CLUE', 'ENGL.G3.READIN.T1_COMPREHENSION.PREDICT', 'Makes a prediction with no link to the clues.', '{"question":"Title: The Big Race. What might the story be about?","wrong_answer":"a wedding","correct_answer":"children running a race"}'::jsonb, 'The child says the first idea that comes, not what the title points to.', 'Offer "a wedding" beside "children running a race" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find a word in the title or picture that helps you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.PREDICT.M3_PR_PAST_EVENT', 'ENGL.G3.READIN.T1_COMPREHENSION.PREDICT', 'Gives something that has already happened.', '{"question":"Juma climbed the tree to get his kite. What will happen next?","wrong_answer":"Juma climbed the tree.","correct_answer":"He will get the kite and climb down."}'::jsonb, 'Already happened and will happen are not kept apart.', 'Offer "Juma climbed the tree." beside "He will get the kite and climb down." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Next means after what we have read.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.PREDICT.M3_PR_FEAR_WRONG', 'ENGL.G3.READIN.T1_COMPREHENSION.PREDICT', 'Will not predict because the guess might be wrong.', '{"question":"Is a prediction wrong if the story ends differently?","wrong_answer":"Yes, it was a mistake.","correct_answer":"No. A prediction is a good guess from clues; we check it as we read."}'::jsonb, 'Fear of a wrong answer: every question has one right answer.', 'Offer "Yes, it was a mistake." beside "No. A prediction is a good guess from clues; we check it as we read." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Good readers guess, then check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING.M3_CS_ANIMALS', 'ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING', 'Thinks only people can be characters.', '{"question":"In the story Hare and Elephant race to the river. Who are the characters?","wrong_answer":"There are no characters; they are animals.","correct_answer":"Hare and Elephant"}'::jsonb, 'Characters are thought of as people only.', 'Offer "There are no characters; they are animals." beside "Hare and Elephant" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Anyone who acts or talks in a story is a character.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING.M3_CS_SETTING_PERSON', 'ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING', 'Gives a person when asked for the setting.', '{"question":"Mama sold tomatoes at Gikomba market. What is the setting?","wrong_answer":"Mama","correct_answer":"Gikomba market"}'::jsonb, 'Setting is a new word and is guessed.', 'Offer "Mama" beside "Gikomba market" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting is where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING.M3_CS_NO_TIME', 'ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING', 'Gives only the place and leaves out the time.', '{"question":"On a cold night, Baraka sat by the fire at home. When and where is the story?","wrong_answer":"at home","correct_answer":"at home on a cold night"}'::jsonb, 'The setting is taught as a place only.', 'Offer "at home" beside "at home on a cold night" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Setting has two parts: where and when.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING.M3_CS_MAIN_ONLY', 'ENGL.G3.READIN.T1_COMPREHENSION.CHARACTERS_SETTING', 'Names only the main character.', '{"question":"Akinyi and her brother helped their grandfather. Name all the characters.","wrong_answer":"Akinyi","correct_answer":"Akinyi, her brother and her grandfather"}'::jsonb, 'The child stops at the first name.', 'Offer "Akinyi" beside "Akinyi, her brother and her grandfather" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read again and list every person or animal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M3_WC_LOOKS_LIKE', 'ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Picks a word that looks like the new word.', '{"question":"The farmer put the hay in the barn. A barn is ...","wrong_answer":"a burn on the skin","correct_answer":"a building on a farm"}'::jsonb, 'The child matches letters, not meaning.', 'Offer "a burn on the skin" beside "a building on a farm" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read the sentence again: what fits?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M3_WC_USUAL_MEANING', 'ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Gives the usual meaning of a word that means something else here.', '{"question":"We sat on the bank of the river. Here bank means ...","wrong_answer":"a place to keep money","correct_answer":"the side of the river"}'::jsonb, 'The meaning the child knows best is used.', 'Offer "a place to keep money" beside "the side of the river" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some words have two meanings: which one fits here?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M3_WC_GIVES_UP', 'ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Says a new word cannot be known without asking.', '{"question":"The road was slippery after the rain, so Ali walked slowly. What does slippery mean?","wrong_answer":"I do not know.","correct_answer":"easy to slide and fall on"}'::jsonb, 'The child does not know that the sentence gives clues.', 'Offer "I do not know." beside "easy to slide and fall on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look for clues: after rain, walked slowly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT.M3_WC_PICTURE_ONLY', 'ENGL.G3.READIN.T1_COMPREHENSION.WORD_FROM_CONTEXT', 'Uses the picture and ignores the sentence.', '{"question":"Picture: a girl and a dog. \"The girl was furious when the dog tore her book.\" Furious means ...","wrong_answer":"happy","correct_answer":"very angry"}'::jsonb, 'The picture shows a smiling girl from earlier; the sentence is not read.', 'Offer "happy" beside "very angry" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The words tell you more than the picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M3_DQ_OWN_LIFE', 'ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Answers from home life, not from the text.', '{"question":"Text: Otieno ate rice for supper. What did Otieno eat for supper?","wrong_answer":"ugali","correct_answer":"rice"}'::jsonb, 'The child answers what is usual at home.', 'Offer "ugali" beside "rice" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the answer in the text and point to it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M3_DQ_WRONG_WORD', 'ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Gives the wrong kind of answer for the question word.', '{"question":"Text: Mary went to the clinic on Monday. Where did Mary go?","wrong_answer":"on Monday","correct_answer":"to the clinic"}'::jsonb, 'Question words (where, when, who) are not yet matched to answers.', 'Offer "on Monday" beside "to the clinic" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Where wants a place, when wants a time, who wants a person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M3_DQ_WORD_MATCH', 'ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Copies the first sentence that has a word from the question.', '{"question":"Text: The goat ate grass. The cow drank water. What did the cow drink?","wrong_answer":"The goat ate grass.","correct_answer":"water"}'::jsonb, 'The child matches a word, not the meaning.', 'Offer "The goat ate grass." beside "water" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the sentence about the cow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS.M3_DQ_YES_ONLY', 'ENGL.G3.READIN.T1_COMPREHENSION.DIRECT_QUESTIONS', 'Answers yes or no to a question that needs more.', '{"question":"Text: Ali was late because the bus broke down. Why was Ali late?","wrong_answer":"Yes.","correct_answer":"because the bus broke down"}'::jsonb, 'Every question is treated as a yes or no question.', 'Offer "Yes." beside "because the bus broke down" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Why wants a reason: because ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE.M3_BE_CHILDREN_IS', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE', 'Uses is with a plural subject.', '{"question":"The children ... playing outside.","wrong_answer":"is","correct_answer":"are"}'::jsonb, 'Children does not end in -s, so the child does not see that it is plural.', 'Offer "is" beside "are" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'More than one: are. Children are, the boys are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE.M3_BE_WE_WAS', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE', 'Uses was with we, you and they.', '{"question":"Yesterday we ... at the market.","wrong_answer":"was","correct_answer":"were"}'::jsonb, 'Was is learnt first and used for every past.', 'Offer "was" beside "were" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I was, he was; we were, they were, you were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE.M3_BE_TIME', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE', 'Uses am, is or are for the past.', '{"question":"Yesterday I ... sick.","wrong_answer":"am","correct_answer":"was"}'::jsonb, 'The present form is the first one learnt.', 'Offer "am" beside "was" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday means past: was or were.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE.M3_BE_DROPPED', 'ENGL.G3.LANGUA.T1_SUBJECT_VERB_AGREEME.VERB_TO_BE', 'Leaves out the verb to be.', '{"question":"My mother ... a teacher.","wrong_answer":"(nothing): My mother a teacher.","correct_answer":"is"}'::jsonb, 'Some home languages join the two ideas without a verb, or the small word is not heard.', 'Offer "(nothing): My mother a teacher." beside "is" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every sentence needs a verb: My mother is a teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS.M3_TL_SAME_HEIGHT', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS', 'Writes tall letters the same height as short ones.', '{"question":"Which word is written right: \"hill\" with h and l tall, or with h and l as short as i?","wrong_answer":"all letters the same height","correct_answer":"h and l taller than i"}'::jsonb, 'The child forms letters one by one and does not compare their heights.', 'Offer "all letters the same height" beside "h and l taller than i" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tall letters touch the top line: b, d, f, h, k, l, t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS.M3_TL_TAIL_ON_LINE', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS', 'Sits g, j, p, q and y on the line with no tail below.', '{"question":"Where does the tail of y go?","wrong_answer":"on the line","correct_answer":"below the line"}'::jsonb, 'The child has learnt that all letters sit on the line.', 'Offer "on the line" beside "below the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tails hang below the line like roots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS.M3_TL_P_TALL', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS', 'Thinks p or q is a tall letter.', '{"question":"Which letter is tall: p, b, a?","wrong_answer":"p","correct_answer":"b"}'::jsonb, 'P and b, q and d look alike turned over.', 'Offer "p" beside "b" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B reaches up; p hangs down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS.M3_TL_CAPS_FOR_TALL', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.TALL_LETTERS', 'Uses a capital to make a letter tall.', '{"question":"Write the word \"bread\".","wrong_answer":"Bread with a capital in the middle: brEad or BRead","correct_answer":"bread"}'::jsonb, 'Capitals look tall, so they are used to show height.', 'Offer "Bread with a capital in the middle: brEad or BRead" beside "bread" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small b is already tall; capitals are only for names and starts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE.M3_HL_CAPS_INSIDE', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE', 'Mixes capital letters inside words.', '{"question":"Copy: My duties at home","wrong_answer":"My DuTies at hoMe","correct_answer":"My duties at home"}'::jsonb, 'Some capitals (D, M) are easier to form and are mixed in.', 'Offer "My DuTies at hoMe" beside "My duties at home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Inside a word, all small letters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE.M3_HL_SIZE', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE', 'Writes letters of very different sizes in one word.', '{"question":"Copy: sweeping","wrong_answer":"swEEPing with big and small letters","correct_answer":"sweeping, even size"}'::jsonb, 'Letters are formed one at a time without looking back.', 'Offer "swEEPing with big and small letters" beside "sweeping, even size" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Short letters fill half the space, all the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE.M3_HL_START_POINT', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE', 'Starts round letters at the bottom, so a, d and g are left open.', '{"question":"Copy: dog","wrong_answer":"a d that looks like cl and an open g","correct_answer":"dog"}'::jsonb, 'Round letters are drawn from the bottom like a u.', 'Offer "a d that looks like cl and an open g" beside "dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start at the top, go round anticlockwise like c, then close it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE.M3_HL_PRESS', 'ENGL.G3.WRITIN.T1_HANDWRITING_LETTERS_.HANDWRITING_LEGIBLE', 'Presses so hard or rubs out so much that the page tears or smudges.', '{"question":"Copy the sentence neatly.","wrong_answer":"dark grooves and holes from rubbing out","correct_answer":"light, even lines"}'::jsonb, 'Worry about mistakes and a tight grip.', 'Offer "dark grooves and holes from rubbing out" beside "light, even lines" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold the pencil lightly; cross out once and go on.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL.M3_FL_FR_SWAP', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL', 'Hears fl and fr as the same sound.', '{"question":"The teacher says \"fly\". Fly or fry?","wrong_answer":"fry","correct_answer":"fly"}'::jsonb, 'L and r are one sound in some home languages.', 'Offer "fry" beside "fly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the tongue: up for fly, curled back for fry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL.M3_DR_DROP_R', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL', 'Misses the r in dr.', '{"question":"The teacher says \"drip\". Drip or dip?","wrong_answer":"dip","correct_answer":"drip"}'::jsonb, 'The second consonant of the cluster is not heard.', 'Offer "dip" beside "drip" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stretch it: d-rrr-ip. Did you hear the r?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL.M3_GL_CL_VOICE', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL', 'Hears gl as cl (g and k swapped).', '{"question":"The teacher says \"glass\". Glass or class?","wrong_answer":"class","correct_answer":"glass"}'::jsonb, 'Voiced and voiceless pairs (g and k) are not told apart in some home languages.', 'Offer "class" beside "glass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hand on the throat: g buzzes, k does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL.M3_FR_F_ONLY', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.BLENDS_DR_FL_FR_GL', 'Picks any word with f when asked for fr.', '{"question":"Which word starts with fr: fan, frog, leg?","wrong_answer":"fan","correct_answer":"frog"}'::jsonb, 'Only the first letter is listened for.', 'Offer "fan" beside "frog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fr is two sounds: f-r-og. Fan is f then a.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS.M3_FI_LAST_ONLY', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS', 'Does only the last step heard.', '{"question":"Stand up, clap twice and sit down.","wrong_answer":"sits down only","correct_answer":"stands, claps twice, sits"}'::jsonb, 'The last step is freshest; the first two are forgotten.', 'Offer "sits down only" beside "stands, claps twice, sits" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold up a finger for each step as you listen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS.M3_FI_ORDER', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS', 'Does the steps in a different order.', '{"question":"Open your book, write your name, then close it.","wrong_answer":"writes the name, then opens the book","correct_answer":"opens, writes, closes"}'::jsonb, 'The child remembers the steps but not their order.', 'Offer "writes the name, then opens the book" beside "opens, writes, closes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Do them in the order you heard: first, then, last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS.M3_FI_POSITION', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS', 'Mixes position words such as on and under.', '{"question":"Put the pencil under the book.","wrong_answer":"puts it on the book","correct_answer":"puts it under the book"}'::jsonb, 'Position words are not yet secure in English.', 'Offer "puts it on the book" beside "puts it under the book" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Under is below; on is on top. Show with your hands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS.M3_FI_COPY', 'ENGL.G3.LISTEN.T2_PRONUNCIATION_AND_VO.FOLLOW_INSTRUCTIONS', 'Watches and copies a classmate instead of listening.', '{"question":"Pick up the red crayon and draw a circle.","wrong_answer":"picks the blue crayon a friend picked","correct_answer":"picks the red crayon and draws a circle"}'::jsonb, 'The child relies on others when unsure of the words.', 'Offer "picks the blue crayon a friend picked" beside "picks the red crayon and draws a circle" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close your eyes, listen, then do it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION.M3_RE_FLAT', 'ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION', 'Reads every sentence in the same flat voice.', '{"question":"Read: \"Help! The goat has run away!\" shouted Juma.","wrong_answer":"flat voice, no excitement","correct_answer":"loud, worried voice for Juma"}'::jsonb, 'The child is busy with the words and does not think about what they mean.', 'Offer "flat voice, no excitement" beside "loud, worried voice for Juma" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: how would Juma say it? Say it like him.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION.M3_RE_NO_PAUSE', 'ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION', 'Reads through full stops without pausing.', '{"question":"Read: It rained. We stayed inside.","wrong_answer":"It rained we stayed inside.","correct_answer":"It rained. (pause) We stayed inside."}'::jsonb, 'Full stops are seen as dots, not as signals to the voice.', 'Offer "It rained we stayed inside." beside "It rained. (pause) We stayed inside." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A full stop means stop and breathe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION.M3_RE_QUESTION_FLAT', 'ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION', 'Reads a yes or no question like a statement.', '{"question":"Read: Is the water clean?","wrong_answer":"voice falls at clean","correct_answer":"voice rises at clean"}'::jsonb, 'Questions in some home languages are marked by a word, not by the voice.', 'Offer "voice falls at clean" beside "voice rises at clean" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The question mark says lift your voice at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION.M3_RE_SAID_VOICE', 'ENGL.G3.READIN.T2_FLUENCY.READ_WITH_EXPRESSION', 'Reads what a character says in the narrator''s voice.', '{"question":"Read: Grandmother said, \"Come and eat, children.\"","wrong_answer":"same voice for both parts","correct_answer":"a kind grandmother voice inside the quotation marks"}'::jsonb, 'The quotation marks are not yet read as a change of speaker.', 'Offer "same voice for both parts" beside "a kind grandmother voice inside the quotation marks" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Inside the marks a person is talking: become that person.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M3_IQ_NOT_THERE', 'ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Says the answer is not in the story when it is shown by clues.', '{"question":"Akinyi sat alone and cried when her goat got lost. How did she feel?","wrong_answer":"It does not say.","correct_answer":"sad"}'::jsonb, 'The child looks only for the exact words.', 'Offer "It does not say." beside "sad" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The writer shows, not tells: crying shows sad.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M3_IQ_FEELING_GUESS', 'ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Picks a feeling word without using the clue.', '{"question":"Baraka jumped up and down when he won the race. How did he feel?","wrong_answer":"tired","correct_answer":"happy"}'::jsonb, 'A feeling is chosen from the child''s own idea.', 'Offer "tired" beside "happy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What does jumping up and down show?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M3_IQ_TOO_FAR', 'ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Makes an answer the clues do not support.', '{"question":"The sky turned dark and the wind blew hard. What will happen soon?","wrong_answer":"There will be an earthquake.","correct_answer":"It will rain."}'::jsonb, 'The child goes beyond the clues.', 'Offer "There will be an earthquake." beside "It will rain." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use only what the clues show.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS.M3_IQ_COPY_LINE', 'ENGL.G3.READIN.T2_COMPREHENSION.INDIRECT_QUESTIONS', 'Copies a line from the text as the answer to why.', '{"question":"Mama took an umbrella. The clouds were heavy. Why did Mama take an umbrella?","wrong_answer":"Mama took an umbrella.","correct_answer":"because it looked like it would rain"}'::jsonb, 'The child copies the sentence the question repeats.', 'Offer "Mama took an umbrella." beside "because it looked like it would rain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The answer is in another sentence: the clouds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO.M3_DO_HE_DO', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO', 'Uses do with he, she or it.', '{"question":"Juma ... his homework every day.","wrong_answer":"do","correct_answer":"does"}'::jsonb, 'The -es on does is not heard as part of the rule for he and she.', 'Offer "do" beside "does" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she, it: does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO.M3_DO_DID_ED', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO', 'Puts a past verb after did.', '{"question":"Did you ... the dishes? (wash)","wrong_answer":"washed","correct_answer":"wash"}'::jsonb, 'Did shows the past, and the child shows it again on the verb.', 'Offer "washed" beside "wash" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Did already says past: the verb stays plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO.M3_DO_DOES_PAST', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO', 'Uses does or do for the past.', '{"question":"Last week she ... the cleaning.","wrong_answer":"does","correct_answer":"did"}'::jsonb, 'The present form is used for all times.', 'Offer "does" beside "did" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Last week: did.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO.M3_DO_I_DOES', 'ENGL.G3.LANGUA.T2_FORMS_OF_THE_VERB_TO.VERB_TO_DO', 'Uses does with I or you.', '{"question":"I ... my duties after school.","wrong_answer":"does","correct_answer":"do"}'::jsonb, 'Does is over-used once learnt.', 'Offer "does" beside "do" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I and you: do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING.M3_WS_RUN_TOGETHER', 'ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING', 'Runs words together with no space.', '{"question":"Which sentence is spaced right?","wrong_answer":"Wesharetheduties.","correct_answer":"We share the duties."}'::jsonb, 'Speech has no gaps, and the child writes as he or she hears.', 'Offer "Wesharetheduties." beside "We share the duties." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put a finger after each word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING.M3_WS_INSIDE_WORD', 'ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING', 'Puts a space inside a word.', '{"question":"Which is right: \"class room work\" or \"classroom work\"?","wrong_answer":"class room work","correct_answer":"classroom work"}'::jsonb, 'Long words are split where the child pauses.', 'Offer "class room work" beside "classroom work" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A word is one block: no gap inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING.M3_WS_HUGE', 'ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING', 'Leaves very large gaps between words.', '{"question":"Which writing is easiest to read?","wrong_answer":"We      share      duties","correct_answer":"We share duties"}'::jsonb, 'The child has heard leave spaces and overdoes it.', 'Offer "We      share      duties" beside "We share duties" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One finger, no more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING.M3_WS_COUNT', 'ENGL.G3.WRITIN.T2_HANDWRITING.WORD_SPACING', 'Cannot count the words in a written sentence.', '{"question":"How many words: \"Mama cooks food.\"","wrong_answer":"4","correct_answer":"3"}'::jsonb, 'Letters and words are not yet told apart.', 'Offer "4" beside "3" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Count the gaps, then add one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN.M3_PL_BL_VOICE', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN', 'Hears pl as bl (p and b swapped).', '{"question":"Which word starts with pl: plate, blade, slate?","wrong_answer":"blade","correct_answer":"plate"}'::jsonb, 'P and b are not kept apart by some speakers.', 'Offer "blade" beside "plate" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hold paper in front of your lips: p puffs, b does not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN.M3_CR_CL_SWAP', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN', 'Hears cr and cl as the same sound.', '{"question":"The teacher says \"crown\". Crown or clown?","wrong_answer":"clown","correct_answer":"crown"}'::jsonb, 'The l and r merger again, after k.', 'Offer "clown" beside "crown" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue back for crown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN.M3_SN_SM', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN', 'Swaps sn and sm.', '{"question":"Which word starts with sn: smell, snake, sun?","wrong_answer":"smell","correct_answer":"snake"}'::jsonb, 'N and m are both nose sounds and sound alike after s.', 'Offer "smell" beside "snake" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For sn the lips stay open; for sm they close.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN.M3_ST_TWO_BEATS', 'ENGL.G3.LISTEN.T3_PRONUNCIATION_AND_VO.BLENDS_CR_PL_ST_SN', 'Hears st as two syllables (si-tone).', '{"question":"Clap the beats in \"stone\".","wrong_answer":"2 (si-tone)","correct_answer":"1"}'::jsonb, 'A vowel is slipped in after s, as the home language does.', 'Offer "2 (si-tone)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ssss-t: hiss straight into t, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA.M3_MI_DETAIL', 'ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA', 'Chooses a detail instead of the main idea.', '{"question":"A text about the ways children help at home: sweeping, washing dishes, feeding hens. What is it mainly about?","wrong_answer":"feeding hens","correct_answer":"how children help at home"}'::jsonb, 'One detail is remembered best.', 'Offer "feeding hens" beside "how children help at home" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Which answer covers every part of the text?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA.M3_MI_TOO_WIDE', 'ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA', 'Chooses an idea that is too wide.', '{"question":"A text about how to care for a dog. What is it mainly about?","wrong_answer":"animals","correct_answer":"caring for a dog"}'::jsonb, 'The child picks a word that is true but covers much more than the text.', 'Offer "animals" beside "caring for a dog" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Is the whole text about that, or a bit of it?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA.M3_MI_FIRST_LINE', 'ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA', 'Takes the first sentence as the main idea every time.', '{"question":"Text starts: \"On Saturday it was sunny.\" It is about washing clothes. Main idea?","wrong_answer":"It was sunny.","correct_answer":"washing clothes on Saturday"}'::jsonb, 'The child has been told the first sentence is important.', 'Offer "It was sunny." beside "washing clothes on Saturday" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it all, then decide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA.M3_MI_PURPOSE', 'ENGL.G3.READIN.T3_COMPREHENSION.MAIN_IDEA', 'Thinks every text tells a story.', '{"question":"A text lists the steps to plant beans. Why was it written?","wrong_answer":"to tell a story","correct_answer":"to tell us how to plant beans"}'::jsonb, 'Most texts the child has read are stories.', 'Offer "to tell a story" beside "to tell us how to plant beans" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Does it have characters, facts, or steps?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE.M3_SU_EVERYTHING', 'ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE', 'Retells everything instead of summarising.', '{"question":"Summarise a ten-sentence story in three sentences.","wrong_answer":"ten sentences, every detail","correct_answer":"three sentences: beginning, middle, end"}'::jsonb, 'The child thinks leaving things out is wrong.', 'Offer "ten sentences, every detail" beside "three sentences: beginning, middle, end" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep only what you need to understand the story.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE.M3_SU_ONE_DETAIL', 'ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE', 'Gives one small detail as the summary.', '{"question":"A story about a boy who saves money to buy a ball. Summary?","wrong_answer":"The coins were in a tin.","correct_answer":"A boy saved money for weeks and bought a ball."}'::jsonb, 'A favourite detail is chosen.', 'Offer "The coins were in a tin." beside "A boy saved money for weeks and bought a ball." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who, what happened, how did it end?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE.M3_SU_OPINION', 'ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE', 'Adds his or her own opinion.', '{"question":"Choose the best summary of the story about the boy who saves money.","wrong_answer":"I liked the boy. Saving is good.","correct_answer":"A boy saved money for weeks and bought a ball."}'::jsonb, 'The child mixes what happened with what he or she thinks.', 'Offer "I liked the boy. Saving is good." beside "A boy saved money for weeks and bought a ball." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A summary says what happened, not what you think.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE.M3_SU_ORDER', 'ENGL.G3.READIN.T3_COMPREHENSION.SUMMARISE', 'Gives the main events out of order.', '{"question":"Summarise: Achieng found a seed, planted it and watered it, and it grew.","wrong_answer":"It grew. She planted a seed.","correct_answer":"Achieng planted a seed, watered it and it grew."}'::jsonb, 'The events are remembered but not their order.', 'Offer "It grew. She planted a seed." beside "Achieng planted a seed, watered it and it grew." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Beginning, middle, end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS.M3_SE_ORDER_TOLD', 'ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS', 'Takes the order the events are told as the order they happened.', '{"question":"Before he went to school, Juma ate breakfast. What did Juma do first?","wrong_answer":"went to school","correct_answer":"ate breakfast"}'::jsonb, 'Before and after are not yet used to reorder events.', 'Offer "went to school" beside "ate breakfast" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Before tells you which came first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS.M3_SE_ENDS_ONLY', 'ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS', 'Gets the first and last events but mixes the middle.', '{"question":"Put in order: woke up, washed, dressed, walked to school.","wrong_answer":"woke up, dressed, washed, walked to school","correct_answer":"woke up, washed, dressed, walked to school"}'::jsonb, 'The middle events are not checked against the text.', 'Offer "woke up, dressed, washed, walked to school" beside "woke up, washed, dressed, walked to school" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find each event in the text and number it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS.M3_SE_AFTER_BEFORE', 'ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS', 'Swaps after and before.', '{"question":"What did Amina do after she fed the hens? (She fed the hens, then fetched water.)","wrong_answer":"She fed the hens.","correct_answer":"She fetched water."}'::jsonb, 'The two words are learnt together and mixed.', 'Offer "She fed the hens." beside "She fetched water." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After means later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS.M3_SE_PICTURE_PLACE', 'ENGL.G3.READIN.T3_COMPREHENSION.SEQUENCE_EVENTS', 'Orders picture cards by where they lie, not by the story.', '{"question":"Put the four pictures of making tea in order.","wrong_answer":"leaves them as they lie","correct_answer":"boil water, add tea leaves, add milk, pour"}'::jsonb, 'The child reads the cards left to right as given.', 'Offer "leaves them as they lie" beside "boil water, add tea leaves, add milk, pour" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask: what must happen first?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE.M3_HV_SHE_HAVE', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE', 'Uses have with he, she or it.', '{"question":"Akinyi ... two sisters.","wrong_answer":"have","correct_answer":"has"}'::jsonb, 'Have is the first form learnt.', 'Offer "have" beside "has" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'He, she, it: has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE.M3_HV_HAVING', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE', 'Says am having for have.', '{"question":"I ... two brothers.","wrong_answer":"am having","correct_answer":"have"}'::jsonb, 'Common Kenyan English: the -ing form is used for having things.', 'Offer "am having" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For what you own, say I have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE.M3_HV_I_HAS', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE', 'Uses has with I, we or they.', '{"question":"We ... a new teacher.","wrong_answer":"has","correct_answer":"have"}'::jsonb, 'Has is over-used once learnt.', 'Offer "has" beside "have" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I, you, we, they: have.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE.M3_HV_PAST', 'ENGL.G3.LANGUA.T3_SUBJECT_VERB_AGREEME.VERB_TO_HAVE', 'Uses has or have for the past.', '{"question":"Yesterday Baraka ... a cold.","wrong_answer":"has","correct_answer":"had"}'::jsonb, 'The present form is used for all times.', 'Offer "has" beside "had" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yesterday: had.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE.M3_LL_FLOAT', 'ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE', 'Writes letters floating above the line.', '{"question":"Which writing is right?","wrong_answer":"letters above the line","correct_answer":"letters sitting on the line"}'::jsonb, 'The line is not seen as the floor.', 'Offer "letters above the line" beside "letters sitting on the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The line is the floor: every letter stands on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE.M3_LL_SLOPE', 'ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE', 'Lets the writing climb or fall across the page.', '{"question":"Which writing is right?","wrong_answer":"a line that rises to the right","correct_answer":"straight along the line"}'::jsonb, 'The child does not look back at the line.', 'Offer "a line that rises to the right" beside "straight along the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check the line after every word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE.M3_LL_TAIL_UP', 'ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE', 'Writes the tails of g and y above the line.', '{"question":"Which \"yes\" is right?","wrong_answer":"y sitting on the line with its tail up","correct_answer":"y with its tail below"}'::jsonb, 'Tails are drawn upward to stay inside the space.', 'Offer "y sitting on the line with its tail up" beside "y with its tail below" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tails go down, under the floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE.M3_LL_MARGIN', 'ENGL.G3.WRITIN.T3_HANDWRITING.LETTERS_ON_LINE', 'Writes into the margin or starts in the middle.', '{"question":"Where does the first word go?","wrong_answer":"in the margin","correct_answer":"just after the margin line"}'::jsonb, 'The margin is not known as a boundary.', 'Offer "in the margin" beside "just after the margin line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start next to the red line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST.M3_WR_W_SOUND', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST', 'Thinks wr starts with a w sound.', '{"question":"Which word starts with the same sound as \"run\": write, wet, win?","wrong_answer":"wet","correct_answer":"write"}'::jsonb, 'The child goes by the first letter, not the sound: the w in wr is silent.', 'Offer "wet" beside "write" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In wr the w is silent: write starts with r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST.M3_PR_BR_VOICE', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST', 'Hears pr as br.', '{"question":"The teacher says \"pride\". Pride or bride?","wrong_answer":"bride","correct_answer":"pride"}'::jsonb, 'P and b are swapped.', 'Offer "bride" beside "pride" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'P puffs air: feel it on your hand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST.M3_SM_SN', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST', 'Hears sm as sn.', '{"question":"The teacher says \"small\". Small or snail?","wrong_answer":"snail","correct_answer":"small"}'::jsonb, 'Two nose sounds after s.', 'Offer "snail" beside "small" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Small: the lips close for m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST.M3_ST_DROP_S', 'ENGL.G3.LISTEN.T4_PRONUNCIATION_AND_VO.BLENDS_WR_PR_SM_ST', 'Does not hear the s in st.', '{"question":"The teacher says \"stop\". Stop or top?","wrong_answer":"top","correct_answer":"stop"}'::jsonb, 'The first consonant of the cluster is lost.', 'Offer "top" beside "stop" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the hiss first: sss-top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS.M3_IN_DOUBLE_NEG', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS', 'Uses nobody with not.', '{"question":"Nobody ... to the meeting.","wrong_answer":"did not come","correct_answer":"came"}'::jsonb, 'Kiswahili hakuna mtu aliyekuja carries a negative, and the child adds not.', 'Offer "did not come" beside "came" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Nobody already means not anybody: Nobody came.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS.M3_IN_PLURAL_VERB', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS', 'Uses a plural verb with somebody or nobody.', '{"question":"Somebody ... knocking at the door.","wrong_answer":"are","correct_answer":"is"}'::jsonb, 'Somebody sounds like it could be many people.', 'Offer "are" beside "is" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Somebody, anybody, nobody: one, so is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS.M3_IN_ANY_SOME', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS', 'Uses somebody after not or in a question.', '{"question":"I did not see ... at the gate.","wrong_answer":"somebody","correct_answer":"anybody"}'::jsonb, 'The rule for some and any is not yet known.', 'Offer "somebody" beside "anybody" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After not and in questions: anybody.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS.M3_IN_ANYBODY_STATEMENT', 'ENGL.G3.LANGUA.T4_INDEFINITE_PRONOUNS.INDEFINITE_PRONOUNS', 'Uses anybody in a plain statement for one unknown person.', '{"question":"... is at the door. Please open it.","wrong_answer":"Anybody","correct_answer":"Somebody"}'::jsonb, 'Anybody and somebody are mixed.', 'Offer "Anybody" beside "Somebody" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One person we do not know, in a statement: somebody.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q.M3_BD_B_D', 'ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q', 'Writes or reads b for d, or d for b.', '{"question":"Which word is right: bed, deb, ded?","wrong_answer":"ded","correct_answer":"bed"}'::jsonb, 'B and d are mirror images and young writers often still mix them.', 'Offer "ded" beside "bed" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Make a bed with your fists: b at the start, d at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q.M3_BD_P_Q', 'ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q', 'Writes p for q or q for p.', '{"question":"Fill in: ...ueen","wrong_answer":"pueen","correct_answer":"queen"}'::jsonb, 'P and q are mirror images.', 'Offer "pueen" beside "queen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Q always has u after it; p has its stick on the left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q.M3_BD_B_P', 'ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q', 'Turns b upside down into p.', '{"question":"Which word is right: pig or big for the animal that says oink?","wrong_answer":"big","correct_answer":"pig"}'::jsonb, 'B and p are the same shape flipped up and down.', 'Offer "big" beside "pig" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'B reaches up; p hangs down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q.M3_BD_WAS_SAW', 'ENGL.G3.WRITIN.T4_HANDWRITING.B_D_P_Q', 'Writes a whole word backwards.', '{"question":"Fill in: Yesterday it ... raining.","wrong_answer":"saw","correct_answer":"was"}'::jsonb, 'The letters are right but the order is turned round.', 'Offer "saw" beside "was" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say each sound as you write it, left to right: w-a-s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR.M3_THR_TR', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR', 'Hears thr as tr.', '{"question":"The teacher says \"three\". Three or tree?","wrong_answer":"tree","correct_answer":"three"}'::jsonb, 'Th is rare in Kenyan home languages and is heard as the nearest sound, t.', 'Offer "tree" beside "three" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Th has the tongue between the teeth: look at the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR.M3_SW_TWO_BEATS', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR', 'Hears a vowel after s in sw.', '{"question":"Clap the beats in \"sweep\".","wrong_answer":"2 (su-weep)","correct_answer":"1"}'::jsonb, 'A vowel is put after each consonant, as in Kiswahili syllables.', 'Offer "2 (su-weep)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S and w together: sweep, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR.M3_SP_ST_S_ONLY', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR', 'Picks any s word for an s blend.', '{"question":"Which word starts with sp: stick, spoon, sun?","wrong_answer":"stick","correct_answer":"spoon"}'::jsonb, 'Only the s is listened for.', 'Offer "stick" beside "spoon" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the second sound: s-p or s-t?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR.M3_SL_DROP_L', 'ENGL.G3.LISTEN.T5_PRONUNCIATION_AND_VO.BLENDS_SL_SW_SP_THR', 'Does not hear the l in sl.', '{"question":"The teacher says \"slow\". Slow or sow?","wrong_answer":"sow","correct_answer":"slow"}'::jsonb, 'The second consonant is lost in a cluster.', 'Offer "sow" beside "slow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stretch it: s-lll-ow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT.M3_RT_READS_AGAIN', 'ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT', 'Reads the text again instead of retelling it.', '{"question":"Tell your friend about the story.","wrong_answer":"reads the book aloud again","correct_answer":"tells the story in own words"}'::jsonb, 'The child thinks retelling means repeating.', 'Offer "reads the book aloud again" beside "tells the story in own words" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Close the book and tell it your way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT.M3_RT_MIDDLE', 'ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT', 'Starts in the middle of the story.', '{"question":"Tell your friend about the story of the lost calf.","wrong_answer":"And then the calf was found.","correct_answer":"Kamau''s calf got lost. He looked everywhere. He found it near the river."}'::jsonb, 'The most exciting part comes first.', 'Offer "And then the calf was found." beside "Kamau''s calf got lost. He looked everywhere. He found it near the river." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with who and what the problem was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT.M3_RT_NO_NAMES', 'ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT', 'Uses he and she without saying who.', '{"question":"Retell the story of Akinyi and her brother.","wrong_answer":"She went and he said and she took it.","correct_answer":"Akinyi went to the river. Her brother said ..."}'::jsonb, 'The child knows who is meant and forgets the listener does not.', 'Offer "She went and he said and she took it." beside "Akinyi went to the river. Her brother said ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say the name first, then he or she.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT.M3_RT_ONE_SENTENCE', 'ENGL.G3.READIN.T5_COMPREHENSION.RETELL_TEXT', 'Says one sentence and stops.', '{"question":"What was your book about?","wrong_answer":"A hare.","correct_answer":"It was about a clever hare who tricked a lion and saved the animals."}'::jsonb, 'The child does not know how much to say.', 'Offer "A hare." beside "It was about a clever hare who tricked a lion and saved the animals." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tell who, what happened and how it ended.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS.M3_PL_ADD_S', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS', 'Adds -s to an irregular noun.', '{"question":"One child, two ...","wrong_answer":"childs","correct_answer":"children"}'::jsonb, 'The -s rule is used for every noun.', 'Offer "childs" beside "children" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some nouns change: child, children.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS.M3_PL_DOUBLE', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS', 'Adds -s to an irregular plural.', '{"question":"The ... are playing.","wrong_answer":"childrens","correct_answer":"children"}'::jsonb, 'The child knows children and adds -s to be sure it is plural.', 'Offer "childrens" beside "children" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Children is already plural: no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS.M3_PL_SHEEPS', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS', 'Adds -s to a noun that stays the same.', '{"question":"The farmer has ten ...","wrong_answer":"sheeps","correct_answer":"sheep"}'::jsonb, 'The -s rule again.', 'Offer "sheeps" beside "sheep" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sheep stays sheep: one sheep, ten sheep.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS.M3_PL_SINGULAR_WRONG', 'ENGL.G3.LANGUA.T5_SINGULAR_AND_PLURALS.IRREGULAR_PLURALS', 'Uses the plural form for one.', '{"question":"I have a pain in one ...","wrong_answer":"teeth","correct_answer":"tooth"}'::jsonb, 'Teeth and feet are heard more often than tooth and foot.', 'Offer "teeth" beside "tooth" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One tooth, many teeth. One foot, two feet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR.M3_SHR_S', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR', 'Hears shr as s, losing sh and r.', '{"question":"The teacher says \"shrink\". Shrink or sink?","wrong_answer":"sink","correct_answer":"shrink"}'::jsonb, 'Sh is heard as s and the r is dropped, both common for Kenyan learners.', 'Offer "sink" beside "shrink" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Round lips for sh, then r: sh-r-ink.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR.M3_GR_GL', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR', 'Hears gr as gl.', '{"question":"The teacher says \"grass\". Grass or glass?","wrong_answer":"glass","correct_answer":"grass"}'::jsonb, 'The l and r merger.', 'Offer "glass" beside "grass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue curled back: grass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR.M3_DR_TR_VOICE', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR', 'Hears dr as tr.', '{"question":"The teacher says \"drain\". Drain or train?","wrong_answer":"train","correct_answer":"drain"}'::jsonb, 'D and t (voiced and voiceless) are swapped.', 'Offer "train" beside "drain" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hand on the throat: d buzzes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR.M3_GR_TWO_BEATS', 'ENGL.G3.LISTEN.T6_PRONUNCIATION_AND_VO.BLENDS_DR_GR_SHR', 'Hears gr as two syllables (gu-row).', '{"question":"Clap the beats in \"grow\".","wrong_answer":"2","correct_answer":"1"}'::jsonb, 'A vowel is slipped between g and r.', 'Offer "2" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G and r glued: grow, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL.M3_FU_WILL_ED', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL', 'Puts a past verb after will.', '{"question":"Tomorrow I will ... my grandmother. (visit)","wrong_answer":"visited","correct_answer":"visit"}'::jsonb, 'The child marks the time on the verb as in the past.', 'Offer "visited" beside "visit" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After will, the verb is plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL.M3_FU_WILL_S', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL', 'Puts -s on the verb after will.', '{"question":"She will ... the computer tomorrow. (use)","wrong_answer":"uses","correct_answer":"use"}'::jsonb, 'The -s for she is carried in.', 'Offer "uses" beside "use" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After will, no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL.M3_FU_WILL_TO', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL', 'Puts to after will.', '{"question":"We will ... a phone call. (make)","wrong_answer":"to make","correct_answer":"make"}'::jsonb, 'Want to and need to are mixed with will.', 'Offer "to make" beside "make" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Will make, never will to make.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL.M3_FU_SHALL_HE', 'ENGL.G3.LANGUA.T6_TENSE_FUTURE_TIME_WI.FUTURE_WILL_SHALL', 'Uses shall with he, she or they in a plain statement.', '{"question":"He ... come tomorrow.","wrong_answer":"shall","correct_answer":"will"}'::jsonb, 'Shall is learnt as another will for everyone.', 'Offer "shall" beside "will" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Shall goes with I and we; use will with he, she and they.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR.M3_SP_SHR_SR', 'ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR', 'Writes sr for shr.', '{"question":"Choose: shrub, srub, sub","wrong_answer":"srub","correct_answer":"shrub"}'::jsonb, 'Sh is heard as s.', 'Offer "srub" beside "shrub" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Shrub starts with sh, then r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR.M3_SP_DR_JR', 'ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR', 'Writes jr or j for dr.', '{"question":"Choose: drive, jrive, jive","wrong_answer":"jrive","correct_answer":"drive"}'::jsonb, 'Dr is said with a j-like sound and spelt as heard.', 'Offer "jrive" beside "drive" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It sounds like j, but we write d-r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR.M3_SP_GR_GL', 'ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR', 'Writes gl for gr.', '{"question":"Choose the word for what cows eat: glass, grass","wrong_answer":"glass","correct_answer":"grass"}'::jsonb, 'The l and r merger shows in spelling.', 'Offer "glass" beside "grass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Grass: g-r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR.M3_SP_EXTRA_VOWEL', 'ENGL.G3.WRITIN.T6_SPELLING.SPELL_DR_GR_SHR', 'Writes a vowel between the consonants.', '{"question":"Choose: garass, grass, gass","wrong_answer":"garass","correct_answer":"grass"}'::jsonb, 'The word is spelt as said with a slipped-in vowel.', 'Offer "garass" beside "grass" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G and r sit together: gr.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ.M3_NK_NG', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ', 'Hears nk as ng.', '{"question":"The teacher says \"sink\". Sink or sing?","wrong_answer":"sing","correct_answer":"sink"}'::jsonb, 'The k after n is soft and missed.', 'Offer "sing" beside "sink" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sink ends with a click of k at the back of the mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ.M3_SQ_SK', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ', 'Hears sq as sk, missing the w sound.', '{"question":"Which word starts like \"squeeze\": square, school, sun?","wrong_answer":"school","correct_answer":"square"}'::jsonb, 'Sq says s-k-w; the w sound is not heard.', 'Offer "school" beside "square" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sq-u: s, k, then round lips for w.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ.M3_TW_TWO_BEATS', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ', 'Hears tw as two syllables (tu-win).', '{"question":"Clap the beats in \"twin\".","wrong_answer":"2","correct_answer":"1"}'::jsonb, 'A vowel is put after t.', 'Offer "2" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'T and w together: twin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ.M3_DW_DR', 'ENGL.G3.LISTEN.T7_PRONUNCIATION_AND_VO.BLENDS_DW_TW_NK_SQ', 'Hears dw as dr.', '{"question":"Which word starts with dw: dwarf, draw, door?","wrong_answer":"draw","correct_answer":"dwarf"}'::jsonb, 'Dw is rare and the child hears the familiar dr.', 'Offer "draw" beside "dwarf" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'For dw the lips go round; for dr the tongue curls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE.M3_CJ_AND_FOR_BUT', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE', 'Uses and for two ideas that pull different ways.', '{"question":"The road was busy ... we crossed safely.","wrong_answer":"and","correct_answer":"but"}'::jsonb, 'And is the joining word used most.', 'Offer "and" beside "but" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Do the ideas agree? If not, but.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE.M3_CJ_REASON_SWAP', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE', 'Puts the reason and the result the wrong way round.', '{"question":"Join: I was hungry. I ate. (because)","wrong_answer":"I was hungry because I ate.","correct_answer":"I ate because I was hungry."}'::jsonb, 'Because is put between the ideas in the order they were given.', 'Offer "I was hungry because I ate." beside "I ate because I was hungry." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Because comes before the reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE.M3_CJ_BECAUSE_ALONE', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE', 'Writes a because part as a full sentence.', '{"question":"Why did you stay inside?","wrong_answer":"Because it was raining. (written alone as the sentence)","correct_answer":"We stayed inside because it was raining."}'::jsonb, 'Spoken answers start with because, and that is written as a sentence.', 'Offer "Because it was raining. (written alone as the sentence)" beside "We stayed inside because it was raining." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Join it to the main idea.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE.M3_CJ_BUT_AGREE', 'ENGL.G3.LANGUA.T7_CONJUNCTIONS.CONJ_BUT_BECAUSE', 'Uses but for two ideas that agree.', '{"question":"I like mangoes ... I like oranges.","wrong_answer":"but","correct_answer":"and"}'::jsonb, 'But is used as another and.', 'Offer "but" beside "and" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ideas that agree: and.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ.M3_SP_SQ_NO_U', 'ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ', 'Leaves out the u after q.', '{"question":"Choose: sqare, square, skare","wrong_answer":"sqare","correct_answer":"square"}'::jsonb, 'The u is not heard as a letter.', 'Offer "sqare" beside "square" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Q never goes without u: squ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ.M3_SP_NK_NG', 'ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ', 'Writes ng for nk.', '{"question":"Choose the word for where we keep money: bang, bank","wrong_answer":"bang","correct_answer":"bank"}'::jsonb, 'Nk is heard as ng.', 'Offer "bang" beside "bank" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bank ends with k.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ.M3_SP_TW_TU', 'ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ', 'Writes tu for tw.', '{"question":"Choose: tuins, twins, tins","wrong_answer":"tuins","correct_answer":"twins"}'::jsonb, 'The w sound is heard as u.', 'Offer "tuins" beside "twins" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tw: t then w.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ.M3_SP_SQ_SKW', 'ENGL.G3.WRITIN.T7_SPELLING.SPELL_DW_TW_NK_SQ', 'Spells squ as skw.', '{"question":"Choose: skwiz, squeeze","wrong_answer":"skwiz","correct_answer":"squeeze"}'::jsonb, 'The word is spelt sound by sound.', 'Offer "skwiz" beside "squeeze" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The sound skw is spelt squ.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES.M3_WT_NO_VERB', 'ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES', 'Writes a group of words with no verb.', '{"question":"Write a sentence about a helmet.","wrong_answer":"A helmet on the head.","correct_answer":"I wear a helmet on my head."}'::jsonb, 'The child writes what he or she sees, not a full idea.', 'Offer "A helmet on the head." beside "I wear a helmet on my head." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who does what? Every sentence needs a doing word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES.M3_WT_RUN_ON', 'ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES', 'Runs sentences together with no full stops.', '{"question":"Write about crossing the road.","wrong_answer":"I stop I look left I look right I cross","correct_answer":"I stop. I look left and right. Then I cross."}'::jsonb, 'Writing follows speech, which has no full stops.', 'Offer "I stop I look left I look right I cross" beside "I stop. I look left and right. Then I cross." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read it aloud; put a full stop where your voice stops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES.M3_WT_LIST', 'ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES', 'Writes a list of words instead of sentences.', '{"question":"Write two sentences about safety.","wrong_answer":"helmet, road, zebra crossing","correct_answer":"We cross at the zebra crossing. I wear a helmet on my bicycle."}'::jsonb, 'Vocabulary practice has been word lists.', 'Offer "helmet, road, zebra crossing" beside "We cross at the zebra crossing. I wear a helmet on my bicycle." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Put each word into a sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES.M3_WT_NO_CAPITAL', 'ENGL.G3.WRITIN.T7_SPELLING.WRITE_THEME_SENTENCES', 'Starts sentences with a small letter.', '{"question":"Write: we walk on the left.","wrong_answer":"we walk on the left.","correct_answer":"We walk on the left."}'::jsonb, 'The capital is forgotten while the child thinks of the words.', 'Offer "we walk on the left." beside "We walk on the left." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every sentence starts with a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD.M3_LT_DROP_T', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD', 'Does not hear the t after l at the end.', '{"question":"The teacher says \"belt\". Belt or bell?","wrong_answer":"bell","correct_answer":"belt"}'::jsonb, 'The last consonant of a cluster is lost.', 'Offer "bell" beside "belt" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen to the very end: bel-t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD.M3_FT_END_VOWEL', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD', 'Hears a vowel after the last consonant.', '{"question":"Clap the beats in \"gift\".","wrong_answer":"2 (gif-ti)","correct_answer":"1"}'::jsonb, 'Home-language words end in a vowel, so one is heard at the end.', 'Offer "2 (gif-ti)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Gift stops at t: no extra sound.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD.M3_CT_RHYME_K', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD', 'Hears -ct as -ck.', '{"question":"Which word ends like \"fact\": act, back, cat?","wrong_answer":"back","correct_answer":"act"}'::jsonb, 'The t after k is quiet and missed.', 'Offer "back" beside "act" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Fact: k then t. Back ends at k.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD.M3_RD_D_T', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.ENDS_FT_CT_LT_RD', 'Hears the d of -rd as t.', '{"question":"The teacher says \"card\". Card or cart?","wrong_answer":"cart","correct_answer":"card"}'::jsonb, 'The voiced d at the end of a word is heard as t.', 'Offer "cart" beside "card" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Card ends with a buzz; cart ends with a puff.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS.M3_PEB_END_VOWEL', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS', 'Adds a vowel at the end of the word.', '{"question":"Say: milk","wrong_answer":"milki","correct_answer":"milk"}'::jsonb, 'Home-language words end in a vowel.', 'Offer "milki" beside "milk" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stop at k: close your mouth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS.M3_PEB_DROP_LAST', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS', 'Drops the last consonant.', '{"question":"Say: hand","wrong_answer":"han","correct_answer":"hand"}'::jsonb, 'The final cluster is reduced.', 'Offer "han" beside "hand" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Touch the tongue up for d at the end: han-d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS.M3_PEB_DEVOICE', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS', 'Says the last d as t.', '{"question":"Say: bird","wrong_answer":"birt","correct_answer":"bird"}'::jsonb, 'Voiced sounds at the end of words are devoiced.', 'Offer "birt" beside "bird" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep the buzz on at the end: bir-d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS.M3_PEB_SILENT_SOUNDED', 'ENGL.G3.LISTEN.T8_PRONUNCIATION_AND_VO.PRONOUNCE_END_BLENDS', 'Sounds a silent letter.', '{"question":"Say: lamb","wrong_answer":"lamb with a b at the end","correct_answer":"lam"}'::jsonb, 'Reading letter by letter: every letter is given a sound.', 'Offer "lamb with a b at the end" beside "lam" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lamb, thumb, walk, half: the b, l and l are silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT.M3_SC_NO_NOTICE', 'ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT', 'Goes on reading after a word that does not make sense.', '{"question":"Read: Amina put on her shoes.","wrong_answer":"Amina put on her shoots. (and goes on)","correct_answer":"stops, rereads: shoes"}'::jsonb, 'The child reads to finish, not to understand.', 'Offer "Amina put on her shoots. (and goes on)" beside "stops, rereads: shoes" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask yourself: does that make sense?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT.M3_SC_RESTART_ALL', 'ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT', 'Starts the whole passage again after every mistake.', '{"question":"The child misreads the last word of line three.","wrong_answer":"starts again from line one","correct_answer":"rereads only the sentence with the mistake"}'::jsonb, 'The child thinks reading must be perfect from the start.', 'Offer "starts again from line one" beside "rereads only the sentence with the mistake" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Go back only to the start of that sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT.M3_SC_SOUND_SIGHT_WORD', 'ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT', 'Sounds out a sight word letter by letter.', '{"question":"Read: the","wrong_answer":"t-h-e","correct_answer":"the"}'::jsonb, 'Every word is treated as one to sound out, even words that do not follow the rules.', 'Offer "t-h-e" beside "the" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some words we just know by sight: the, said, was.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT.M3_SC_WAIT', 'ENGL.G3.READIN.T8_FLUENCY.SELF_CORRECT', 'Stops and waits for the teacher to say the word.', '{"question":"The child meets the word \"festival\".","wrong_answer":"stops and looks at the teacher","correct_answer":"breaks it up: fes-ti-val"}'::jsonb, 'The child is used to being told the word.', 'Offer "stops and looks at the teacher" beside "breaks it up: fes-ti-val" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Try first: break it into beats.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS.M3_QT_MANY_UNCOUNT', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS', 'Uses many with things we do not count.', '{"question":"The cow gives ... milk.","wrong_answer":"many","correct_answer":"a lot of"}'::jsonb, 'Many is used for every large amount.', 'Offer "many" beside "a lot of" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Can you count it? Milk, no: much or a lot of.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS.M3_QT_MUCH_COUNT', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS', 'Uses much with things we count.', '{"question":"There are ... goats on the farm.","wrong_answer":"much","correct_answer":"many"}'::jsonb, 'Much and many mean a large amount and are mixed.', 'Offer "much" beside "many" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Goats can be counted: many.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS.M3_QT_LOT_NO_OF', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS', 'Leaves out of after a lot.', '{"question":"We have a lot ... hens.","wrong_answer":"(nothing): a lot hens","correct_answer":"of"}'::jsonb, 'The small word of is not heard in fast speech.', 'Offer "(nothing): a lot hens" beside "of" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A lot of: three words.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS.M3_QT_FEW_UNCOUNT', 'ENGL.G3.LANGUA.T8_QUANTIFIERS.QUANTIFIERS', 'Uses a few with things we do not count.', '{"question":"Give the calf ... water.","wrong_answer":"a few","correct_answer":"some"}'::jsonb, 'A few is used for any small amount.', 'Offer "a few" beside "some" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Water cannot be counted: some or a little.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD.M3_SP_DROP_LAST', 'ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD', 'Leaves out the last consonant.', '{"question":"Choose: gif, gift, gifd","wrong_answer":"gif","correct_answer":"gift"}'::jsonb, 'The last sound is not heard.', 'Offer "gif" beside "gift" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Gift ends with f and t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD.M3_SP_CT_CK', 'ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD', 'Writes ck or k for ct.', '{"question":"Choose: insekt, inseck, insect","wrong_answer":"inseck","correct_answer":"insect"}'::jsonb, 'The t after c is quiet.', 'Offer "inseck" beside "insect" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Insect ends with c then t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD.M3_SP_END_VOWEL', 'ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD', 'Adds a vowel at the end.', '{"question":"Choose: belti, belt","wrong_answer":"belti","correct_answer":"belt"}'::jsonb, 'The word is spelt as said with a final vowel.', 'Offer "belti" beside "belt" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Belt stops at t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD.M3_SP_RD_RT', 'ENGL.G3.WRITIN.T8_SPELLING.SPELL_FT_CT_LT_RD', 'Writes rt for rd.', '{"question":"Choose: birt, bird","wrong_answer":"birt","correct_answer":"bird"}'::jsonb, 'The final d is said as t.', 'Offer "birt" beside "bird" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bird ends with d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP.M3_LK_SILENT_L', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP', 'Thinks the l is always heard in -lk.', '{"question":"In which word do you hear the l: milk or walk?","wrong_answer":"walk","correct_answer":"milk"}'::jsonb, 'Spelling is trusted over sound: in walk, talk and chalk the l is silent.', 'Offer "walk" beside "milk" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Milk, silk: l heard. Walk, talk, chalk: l silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP.M3_LF_DROP_F', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP', 'Does not hear the f in -lf.', '{"question":"The teacher says \"shelf\". Shelf or shell?","wrong_answer":"shell","correct_answer":"shelf"}'::jsonb, 'The last consonant of a cluster is lost.', 'Offer "shell" beside "shelf" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen to the end: shel-f.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP.M3_LM_EXTRA_VOWEL', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP', 'Hears a vowel between l and m.', '{"question":"Clap the beats in \"film\".","wrong_answer":"2 (fi-lim)","correct_answer":"1"}'::jsonb, 'A vowel is put between l and m, as in common Kenyan English.', 'Offer "2 (fi-lim)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Film is one beat: fi-lm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP.M3_MP_MB', 'ENGL.G3.LISTEN.T9_PRONUNCIATION_AND_VO.ENDS_LK_LF_LM_MP', 'Hears -mp as -mb.', '{"question":"The teacher says \"lamp\". Lamp or lamb?","wrong_answer":"lamb","correct_answer":"lamp"}'::jsonb, 'The p at the end is soft and missed.', 'Offer "lamb" beside "lamp" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lamp ends with a puff: p.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE.M3_VI_ONE_DETAIL', 'ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE', 'Matches one describing word and ignores the others.', '{"question":"Text: a tall, thin man in a red hat. Which picture?","wrong_answer":"a short, fat man in a red hat","correct_answer":"a tall, thin man in a red hat"}'::jsonb, 'One detail (red hat) is held in mind.', 'Offer "a short, fat man in a red hat" beside "a tall, thin man in a red hat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check every describing word: tall, thin, red hat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE.M3_VI_OWN_DETAIL', 'ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE', 'Adds details the text did not give and rejects the right picture.', '{"question":"Text: Amina''s house had a blue door. Which picture fits?","wrong_answer":"rejects the blue-door picture because the house is not like Amina''s in real life","correct_answer":"the house with a blue door"}'::jsonb, 'The child pictures his or her own home.', 'Offer "rejects the blue-door picture because the house is not like Amina''s in real life" beside "the house with a blue door" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Picture only what the words say.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE.M3_VI_TIME', 'ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE', 'Ignores when it happened.', '{"question":"Text: Under the bright moon, the children danced. Which picture?","wrong_answer":"children dancing in the sun","correct_answer":"children dancing at night"}'::jsonb, 'The time word is skipped.', 'Offer "children dancing in the sun" beside "children dancing at night" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Moon means night.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE.M3_VI_WHO_DOES', 'ENGL.G3.READIN.T9_COMPREHENSION.VISUALISE', 'Pictures the wrong character doing the action.', '{"question":"Text: The small dog chased the big cat. Which picture?","wrong_answer":"a big cat chasing a small dog","correct_answer":"a small dog chasing a big cat"}'::jsonb, 'The child pictures what usually happens.', 'Offer "a big cat chasing a small dog" beside "a small dog chasing a big cat" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who is doing the chasing? Picture that.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES.M3_OP_NOT', 'ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES', 'Adds not or un- instead of giving the opposite word.', '{"question":"The opposite of big is ...","wrong_answer":"unbig","correct_answer":"small"}'::jsonb, 'Un- is learnt for unhappy and used on every word.', 'Offer "unbig" beside "small" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Some opposites are a new word: big and small.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES.M3_OP_NEAR', 'ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES', 'Gives a word close in meaning but not the opposite.', '{"question":"The opposite of hot is ...","wrong_answer":"warm","correct_answer":"cold"}'::jsonb, 'The child gives the next step, not the far end.', 'Offer "warm" beside "cold" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The opposite is as far away as you can go: cold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES.M3_OP_SAME', 'ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES', 'Gives a word with the same meaning.', '{"question":"The opposite of wild is ...","wrong_answer":"fierce","correct_answer":"tame"}'::jsonb, 'Same and opposite are mixed.', 'Offer "fierce" beside "tame" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Opposite means the other way: wild animals, tame animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES.M3_OP_OLD', 'ENGL.G3.LANGUA.T9_OPPOSITES.OPPOSITES', 'Gives the wrong opposite for a word with two opposites.', '{"question":"The baby elephant is young; its mother is ...","wrong_answer":"new","correct_answer":"old"}'::jsonb, 'Old has two opposites (young and new) and the wrong one is chosen.', 'Offer "new" beside "old" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Living things: old and young. Things: old and new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M3_CO_NONE', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Leaves out the commas in a list.', '{"question":"Punctuate: We saw lions zebras giraffes and elephants.","wrong_answer":"We saw lions zebras giraffes and elephants.","correct_answer":"We saw lions, zebras, giraffes and elephants."}'::jsonb, 'The child does not hear where commas go.', 'Offer "We saw lions zebras giraffes and elephants." beside "We saw lions, zebras, giraffes and elephants." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A comma between each item, and before the last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M3_CO_AND_EVERY', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Joins every item with and.', '{"question":"Write the list: drums, flags, balloons, sweets.","wrong_answer":"drums and flags and balloons and sweets","correct_answer":"drums, flags, balloons and sweets"}'::jsonb, 'In speech and is repeated; the comma is not yet used.', 'Offer "drums and flags and balloons and sweets" beside "drums, flags, balloons and sweets" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Commas in place of and, except the last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M3_CO_FULL_STOPS', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Uses full stops between the items.', '{"question":"Punctuate: I bought rice beans and sugar.","wrong_answer":"I bought rice. beans. and sugar.","correct_answer":"I bought rice, beans and sugar."}'::jsonb, 'Full stop and comma are both dots and are mixed.', 'Offer "I bought rice. beans. and sugar." beside "I bought rice, beans and sugar." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A comma has a tail and keeps the sentence going.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST.M3_CO_AFTER_AND', 'ENGL.G3.WRITIN.T9_PUNCTUATION_THE_COMM.COMMA_LIST', 'Puts a comma after and.', '{"question":"Punctuate: tea, bread and, milk","wrong_answer":"tea, bread and, milk","correct_answer":"tea, bread and milk"}'::jsonb, 'The child puts a comma after every joining point.', 'Offer "tea, bread and, milk" beside "tea, bread and milk" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'No comma right after and.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH.M3_MB_B_SOUNDED', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH', 'Thinks the b in -mb is heard.', '{"question":"In \"thumb\", do you hear a b at the end?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Spelling is trusted over sound.', 'Offer "yes" beside "no" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Thumb, lamb, comb, climb: the b is silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH.M3_NT_ND_VOICE', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH', 'Hears -nt as -nd.', '{"question":"The teacher says \"bent\". Bent or bend?","wrong_answer":"bend","correct_answer":"bent"}'::jsonb, 'T and d at the end are swapped.', 'Offer "bend" beside "bent" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Bent ends with a puff, bend with a buzz.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH.M3_NCH_NSH', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH', 'Hears -nch as -nsh.', '{"question":"Which word ends with the sound in \"lunch\": bench, bush, push?","wrong_answer":"bush","correct_answer":"bench"}'::jsonb, 'Ch and sh are not kept apart.', 'Offer "bush" beside "bench" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Lunch ends with a stop: t-sh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH.M3_ND_DROP_D', 'ENGL.G3.LISTEN.T10_PRONUNCIATION_AND_VO.ENDS_MB_NT_ND_NCH', 'Does not hear the d in -nd.', '{"question":"The teacher says \"band\". Band or ban?","wrong_answer":"ban","correct_answer":"band"}'::jsonb, 'The last consonant is lost.', 'Offer "ban" beside "band" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the d: ban-d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M3_PP_IN_ON', 'ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses in for on a surface.', '{"question":"The book is ... the table.","wrong_answer":"in","correct_answer":"on"}'::jsonb, 'Kiswahili kwenye covers both in and on.', 'Offer "in" beside "on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'On the top of it: on. Inside: in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M3_PP_BETWEEN_ONE', 'ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses between with only one thing.', '{"question":"The cat is sitting ... the chair. (next to it)","wrong_answer":"between","correct_answer":"beside"}'::jsonb, 'Between is used for any near place.', 'Offer "between" beside "beside" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Between needs two things, one on each side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M3_PP_BEHIND_FRONT', 'ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Swaps behind and in front of.', '{"question":"Picture: a boy hidden by a tree. The boy is ... the tree.","wrong_answer":"in front of","correct_answer":"behind"}'::jsonb, 'The child takes his or her own view, not the tree''s.', 'Offer "in front of" beside "behind" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Behind: the tree hides you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS.M3_PP_ABOVE_ON', 'ENGL.G3.LANGUA.T10_PREPOSITIONS.PREPOSITIONS', 'Uses above for on (touching).', '{"question":"The cup is ... the table.","wrong_answer":"above","correct_answer":"on"}'::jsonb, 'Above and on both mean higher.', 'Offer "above" beside "on" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Above does not touch; on touches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS.M3_CA_NAMES', 'ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS', 'Writes names of people and places with a small letter.', '{"question":"Correct: juma went to mombasa for eid.","wrong_answer":"Juma went to mombasa for eid.","correct_answer":"Juma went to Mombasa for Eid."}'::jsonb, 'Only the first word of the sentence is remembered.', 'Offer "Juma went to mombasa for eid." beside "Juma went to Mombasa for Eid." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Names of people, places, days and festivals get capitals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS.M3_CA_SMALL_I', 'ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS', 'Writes i for I.', '{"question":"Correct: my friend and i danced.","wrong_answer":"My friend and i danced.","correct_answer":"My friend and I danced."}'::jsonb, 'I looks like any small word.', 'Offer "My friend and i danced." beside "My friend and I danced." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'I on its own is always a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS.M3_CA_EXTRA', 'ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS', 'Puts capitals on ordinary words.', '{"question":"Which is right?","wrong_answer":"My Mother cooked Rice.","correct_answer":"My mother cooked rice."}'::jsonb, 'Important words are given capitals.', 'Offer "My Mother cooked Rice." beside "My mother cooked rice." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only starts and names.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS.M3_CA_AFTER_STOP', 'ENGL.G3.WRITIN.T10_PUNCTUATION.CAPITAL_LETTERS', 'Forgets the capital after a full stop.', '{"question":"Correct: We sang. we danced.","wrong_answer":"We sang. we danced.","correct_answer":"We sang. We danced."}'::jsonb, 'Only the first sentence of the piece is given a capital.', 'Offer "We sang. we danced." beside "We sang. We danced." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After every full stop, a capital.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS.M3_EM_QUESTION_STOP', 'ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS', 'Ends a question with a full stop.', '{"question":"Which mark: Where is the festival","wrong_answer":".","correct_answer":"?"}'::jsonb, 'Full stops are used for every sentence.', 'Offer "." beside "?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Asking? Question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS.M3_EM_NONE', 'ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS', 'Leaves out the end mark.', '{"question":"Correct: The drums were loud","wrong_answer":"The drums were loud","correct_answer":"The drums were loud."}'::jsonb, 'The end of the line is taken as the end of the sentence.', 'Offer "The drums were loud" beside "The drums were loud." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Every sentence ends with a mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS.M3_EM_EXCLAIM_ALL', 'ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS', 'Uses exclamation marks everywhere.', '{"question":"Which mark: We ate rice for lunch","wrong_answer":"!","correct_answer":"."}'::jsonb, 'Exclamation marks look exciting.', 'Offer "!" beside "." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Only strong feelings get !', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS.M3_EM_LINE_END', 'ENGL.G3.WRITIN.T10_PUNCTUATION.END_MARKS', 'Puts a full stop at the end of every line.', '{"question":"A sentence goes onto the next line. Where is the full stop?","wrong_answer":"at the end of the first line","correct_answer":"at the end of the sentence"}'::jsonb, 'The line is taken as the unit of writing.', 'Offer "at the end of the first line" beside "at the end of the sentence" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The mark goes where the idea ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND.M3_NKL_NGL', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND', 'Hears -nkl- as -ngl-.', '{"question":"The teacher says \"ankle\". Ankle or angle?","wrong_answer":"angle","correct_answer":"ankle"}'::jsonb, 'K after n is soft and heard as g.', 'Offer "angle" beside "ankle" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ankle has a click of k: an-kle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND.M3_PT_DROP_T', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND', 'Does not hear the t in -pt.', '{"question":"Which word ends with pt: kept, keep, cap?","wrong_answer":"keep","correct_answer":"kept"}'::jsonb, 'The last consonant is lost.', 'Offer "keep" beside "kept" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Kept: p then t.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND.M3_NTH_NT', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND', 'Hears -nth as -nt.', '{"question":"The teacher says \"tenth\". Tenth or tent?","wrong_answer":"tent","correct_answer":"tenth"}'::jsonb, 'Th is heard as t.', 'Offer "tent" beside "tenth" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tenth ends with the tongue between the teeth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND.M3_ND_NG', 'ENGL.G3.LISTEN.T11_PRONUNCIATION_AND_VO.BLENDS_NKL_PT_NTH_ND', 'Hears -nd as -ng.', '{"question":"The teacher says \"sand\". Sand or sang?","wrong_answer":"sang","correct_answer":"sand"}'::jsonb, 'N and ng are both nose sounds.', 'Offer "sang" beside "sand" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Sand: the tongue tip touches behind the teeth for d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST.M3_CM_MORE_ER', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST', 'Uses more with an -er word.', '{"question":"A giraffe is ... than a zebra.","wrong_answer":"more taller","correct_answer":"taller"}'::jsonb, 'Two ways of comparing are put together.', 'Offer "more taller" beside "taller" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Taller already means more tall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST.M3_CM_ER_FOR_EST', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST', 'Uses -er for three or more.', '{"question":"Akinyi is the ... runner in the class. (fast)","wrong_answer":"faster","correct_answer":"fastest"}'::jsonb, 'The two forms are not linked to two and many.', 'Offer "faster" beside "fastest" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Two things: -er. The whole group: the -est.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST.M3_CM_NO_DOUBLE', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST', 'Does not double the last letter.', '{"question":"An elephant is ... than a lion. (big)","wrong_answer":"biger","correct_answer":"bigger"}'::jsonb, 'The spelling rule (short vowel, one consonant: double it) is not known.', 'Offer "biger" beside "bigger" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Big, bigger, biggest: double the g.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST.M3_CM_Y_TO_I', 'ENGL.G3.LANGUA.T11_ADJECTIVES_COMPARATI.COMPARE_ER_EST', 'Keeps the y before -er or -est.', '{"question":"Today I am ... than yesterday. (happy)","wrong_answer":"happyer","correct_answer":"happier"}'::jsonb, 'The y to i rule is not known.', 'Offer "happyer" beside "happier" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Change y to i: happier, happiest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS.M3_PW_SOUND_SPELL', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS', 'Spells the picture word as it sounds.', '{"question":"Write the name: (picture of a football)","wrong_answer":"futbol","correct_answer":"football"}'::jsonb, 'Spelling by sound alone.', 'Offer "futbol" beside "football" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Look at the word, cover, write, check.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS.M3_PW_NEAR_THING', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS', 'Writes the name of something near the object.', '{"question":"Write the name: (picture of a net in a goal)","wrong_answer":"goal","correct_answer":"net"}'::jsonb, 'The bigger or better-known thing is named.', 'Offer "goal" beside "net" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Point at the object first, then name it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS.M3_PW_PLURAL', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS', 'Writes a plural for one object.', '{"question":"Write the name: (one whistle)","wrong_answer":"whistles","correct_answer":"whistle"}'::jsonb, 'The -s is added from habit.', 'Offer "whistles" beside "whistle" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'One thing: no -s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS.M3_PW_HOME_WORD', 'ENGL.G3.WRITIN.T11_GUIDED_WRITING.PICTURE_WORDS', 'Writes the Kiswahili or home name.', '{"question":"Write the English name: (picture of a ball)","wrong_answer":"mpira","correct_answer":"ball"}'::jsonb, 'The home word comes first to mind.', 'Offer "mpira" beside "ball" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Say it in English: ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW.M3_EW_E_SOUND', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW', 'Thinks ew says the short e of bed.', '{"question":"Which word has the same ending sound as \"new\": few, net, hen?","wrong_answer":"net","correct_answer":"few"}'::jsonb, 'The child reads e as /e/ and does not know ew as one sound.', 'Offer "net" beside "few" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'E and w together say oo or you: new, few, grew.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW.M3_GR_CR_VOICE', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW', 'Hears gr as cr.', '{"question":"The teacher says \"grow\". Grow or crow?","wrong_answer":"crow","correct_answer":"grow"}'::jsonb, 'G and k are swapped.', 'Offer "crow" beside "grow" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'G buzzes in the throat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW.M3_PR_PL', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW', 'Hears pr as pl.', '{"question":"The teacher says \"pray\". Pray or play?","wrong_answer":"play","correct_answer":"pray"}'::jsonb, 'The l and r merger.', 'Offer "play" beside "pray" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Pray: curl the tongue.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW.M3_EW_OW', 'ENGL.G3.LISTEN.T12_PRONUNCIATION_AND_VO.BLENDS_GR_PR_EW', 'Hears ew as ow.', '{"question":"Which word has the oo sound: grew, grow, grey?","wrong_answer":"grow","correct_answer":"grew"}'::jsonb, 'The two spellings look alike and the vowels are close.', 'Offer "grow" beside "grew" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Grew says oo; grow says oh.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS.M3_PO_HIS_HER', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS', 'Uses his for a girl or her for a boy.', '{"question":"Amina lost ... pencil.","wrong_answer":"his","correct_answer":"her"}'::jsonb, 'Kiswahili yake means his or her, so the English pair is not separated.', 'Offer "his" beside "her" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Amina is a girl: her. Juma is a boy: his.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS.M3_PO_MINE_NOUN', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS', 'Puts mine before a noun.', '{"question":"This is ... book.","wrong_answer":"mine","correct_answer":"my"}'::jsonb, 'Mine and my are mixed.', 'Offer "mine" beside "my" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'My goes before a noun; mine stands alone: the book is mine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS.M3_PO_APOSTROPHE', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS', 'Writes an apostrophe in yours, hers or ours.', '{"question":"This pen is ...","wrong_answer":"your''s","correct_answer":"yours"}'::jsonb, 'The apostrophe of Amina''s pen is copied.', 'Offer "your''s" beside "yours" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Yours, hers, ours, theirs: no apostrophe.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS.M3_PO_OBJECT_FORM', 'ENGL.G3.LANGUA.T12_PRONOUNS_POSSESSIVE_.POSSESSIVE_PRONOUNS', 'Uses me, him or her for mine, his or hers.', '{"question":"Whose bag is this? It is ...","wrong_answer":"me","correct_answer":"mine"}'::jsonb, 'A word-for-word answer (ni yangu) is turned into it is me.', 'Offer "me" beside "mine" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'It belongs to me: it is mine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA.M3_JM_FIRST', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA', 'Takes the first jumbled sentence as the main idea.', '{"question":"Jumbled: \"We rest under trees.\" \"Food gives us energy.\" \"Eat fruit every day.\" What are they about?","wrong_answer":"resting under trees","correct_answer":"eating good food"}'::jsonb, 'The first sentence is trusted as the topic.', 'Offer "resting under trees" beside "eating good food" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Read all of them; what do most share?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA.M3_JM_DETAIL', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA', 'Chooses a detail as the idea.', '{"question":"Sentences about washing hands, cooking food well and boiling water. What are they about?","wrong_answer":"boiling water","correct_answer":"keeping away diseases"}'::jsonb, 'One sentence stands out.', 'Offer "boiling water" beside "keeping away diseases" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Which answer covers every sentence?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA.M3_JM_ODD_ONE', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA', 'Cannot spot the sentence that does not belong.', '{"question":"Which does not belong: Wash fruit. Boil water. My uncle has a car. Cover food.","wrong_answer":"Boil water.","correct_answer":"My uncle has a car."}'::jsonb, 'Every sentence is accepted as part of the group.', 'Offer "Boil water." beside "My uncle has a car." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Does it fit the main idea?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA.M3_JM_TOO_WIDE', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.JUMBLED_MAIN_IDEA', 'Gives a title that is too wide.', '{"question":"Best title for sentences on washing hands and boiling water?","wrong_answer":"Water","correct_answer":"Keeping Clean to Stay Healthy"}'::jsonb, 'A word that appears is chosen.', 'Offer "Water" beside "Keeping Clean to Stay Healthy" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Does the title fit all and only these sentences?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES.M3_OS_AS_GIVEN', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES', 'Copies the sentences in the order given.', '{"question":"Order: \"Then she cooked.\" \"First Amina washed her hands.\" \"Finally she ate.\"","wrong_answer":"Then she cooked. First Amina washed... Finally she ate.","correct_answer":"First Amina washed her hands. Then she cooked. Finally she ate."}'::jsonb, 'The task is seen as copying.', 'Offer "Then she cooked. First Amina washed... Finally she ate." beside "First Amina washed her hands. Then she cooked. Finally she ate." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Find the first one by its clue word.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES.M3_OS_END_FIRST', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES', 'Puts the ending first.', '{"question":"Which comes first?","wrong_answer":"Finally she ate.","correct_answer":"First Amina washed her hands."}'::jsonb, 'The most important event is put first.', 'Offer "Finally she ate." beside "First Amina washed her hands." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Finally belongs at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES.M3_OS_PRONOUN_FIRST', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES', 'Puts a he or she sentence before the name.', '{"question":"Which comes first: \"She washed the plates.\" or \"Wanjiru finished eating.\"?","wrong_answer":"She washed the plates.","correct_answer":"Wanjiru finished eating."}'::jsonb, 'The child does not see that she refers back to a name.', 'Offer "She washed the plates." beside "Wanjiru finished eating." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The name comes first; then she.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES.M3_OS_ONE_PER_LINE', 'ENGL.G3.WRITIN.T12_PARAGRAPHS.ORDER_SENTENCES', 'Writes each ordered sentence on a new line.', '{"question":"Write the sentences as a paragraph.","wrong_answer":"one sentence on each line, like a list","correct_answer":"one sentence after another on the line"}'::jsonb, 'A paragraph is not yet known as a block.', 'Offer "one sentence on each line, like a list" beside "one sentence after another on the line" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep writing on the same line until the paragraph ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL.M3_SPL_SPR', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL', 'Hears spl as spr.', '{"question":"The teacher says \"splash\". Splash or sprash?","wrong_answer":"sprash","correct_answer":"splash"}'::jsonb, 'The l and r merger.', 'Offer "sprash" beside "splash" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Tongue up for l: spl-ash.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL.M3_LF_RF_SWAP', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL', 'Cannot tell -lf from -rf.', '{"question":"The teacher says \"self\". Does it end with -lf or -rf?","wrong_answer":"-rf","correct_answer":"-lf"}'::jsonb, 'The l and r merger at the end of a word.', 'Offer "-rf" beside "-lf" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Self: tongue up for l before f.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL.M3_SPL_EXTRA_VOWELS', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL', 'Hears vowels between the three consonants.', '{"question":"Clap the beats in \"splash\".","wrong_answer":"3 (si-pu-lash)","correct_answer":"1"}'::jsonb, 'A vowel after every consonant, as in the home language.', 'Offer "3 (si-pu-lash)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'S-p-l glued: splash, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL.M3_LF_SILENT_L', 'ENGL.G3.LISTEN.T13_PRONUNCIATION_AND_VO.BLENDS_LF_RF_SPL', 'Thinks the l is always heard in -lf.', '{"question":"In \"half\", do you hear an l?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Spelling is trusted over sound: in half and calf the l is silent.', 'Offer "yes" beside "no" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Shelf, self: l heard. Half, calf: l silent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW.M3_WH_NO_INVERSION', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW', 'Keeps the statement order in a question.', '{"question":"Ask Ali the reason he is late.","wrong_answer":"Why you are late?","correct_answer":"Why are you late?"}'::jsonb, 'Kiswahili and spoken Kenyan English ask with the statement order.', 'Offer "Why you are late?" beside "Why are you late?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'After why, swap: are you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW.M3_WH_WHOM_SUBJECT', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW', 'Uses whom for the person who does the action.', '{"question":"... came to visit you?","wrong_answer":"Whom","correct_answer":"Who"}'::jsonb, 'Whom is thought to be the polite who.', 'Offer "Whom" beside "Who" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The doer: who. The one the action is done to: whom did you call?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW.M3_WH_WRONG_WORD', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW', 'Chooses a question word that does not fit the answer.', '{"question":"... did you travel to Mombasa? By bus.","wrong_answer":"Why","correct_answer":"How"}'::jsonb, 'How and why both ask for more than a fact and are mixed.', 'Offer "Why" beside "How" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How asks the way; why asks the reason.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW.M3_WH_NO_MARK', 'ENGL.G3.LANGUA.T13_WH_QUESTIONS.WH_WHY_WHOM_HOW', 'Ends a written question with a full stop.', '{"question":"Write: How did you save the money","wrong_answer":"How did you save the money.","correct_answer":"How did you save the money?"}'::jsonb, 'Every sentence is closed with a full stop.', 'Offer "How did you save the money." beside "How did you save the money?" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A question ends with a question mark.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH.M3_WP_AND_THEN', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH', 'Joins every sentence with and then.', '{"question":"Write a paragraph about saving money.","wrong_answer":"I got money and then I put it in a tin and then ...","correct_answer":"I got ten shillings. I put it in my tin. After a month I had enough."}'::jsonb, 'And then is the joining phrase of speech.', 'Offer "I got money and then I put it in a tin and then ..." beside "I got ten shillings. I put it in my tin. After a month I had enough." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Use full stops, and try after, next and so.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH.M3_WP_OFF_TOPIC', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH', 'Moves away from the topic.', '{"question":"Write a paragraph about saving.","wrong_answer":"I save money. My cat is black. I like chapati.","correct_answer":"I save money in a tin. I save for books. Saving helps me buy what I need."}'::jsonb, 'Each new sentence follows the last thought, not the topic.', 'Offer "I save money. My cat is black. I like chapati." beside "I save money in a tin. I save for books. Saving helps me buy what I need." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Check each sentence: is it about saving?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH.M3_WP_SAME_START', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH', 'Starts every sentence the same way.', '{"question":"Write about your savings.","wrong_answer":"I save. I put. I count. I buy.","correct_answer":"I save coins. Every Friday, I count them. Soon I will buy a ball."}'::jsonb, 'One safe pattern is repeated.', 'Offer "I save. I put. I count. I buy." beside "I save coins. Every Friday, I count them. Soon I will buy a ball." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start some sentences with a time word or a name.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH.M3_WP_LIST_LINES', 'ENGL.G3.WRITIN.T13_GUIDED_WRITING.WRITE_PARAGRAPH', 'Writes one sentence per line.', '{"question":"Write a paragraph of four sentences.","wrong_answer":"four short lines like a list","correct_answer":"four sentences in one block"}'::jsonb, 'A paragraph is not yet seen as a block.', 'Offer "four short lines like a list" beside "four sentences in one block" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep going on the same line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR.M3_STR_EXTRA_VOWELS', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR', 'Hears vowels between s, t and r.', '{"question":"Clap the beats in \"street\".","wrong_answer":"3 (si-ti-reet)","correct_answer":"1"}'::jsonb, 'A vowel after every consonant.', 'Offer "3 (si-ti-reet)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Str glued: street, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR.M3_SPR_SPL', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR', 'Hears spr as spl.', '{"question":"The teacher says \"spring\". Spring or spling?","wrong_answer":"spling","correct_answer":"spring"}'::jsonb, 'The l and r merger.', 'Offer "spling" beside "spring" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Curl the tongue: spr-ing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR.M3_STR_SPR_SWAP', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR', 'Mixes str and spr.', '{"question":"Which word starts with str: spring, string, sing?","wrong_answer":"spring","correct_answer":"string"}'::jsonb, 'The middle sound of the cluster is not heard.', 'Offer "spring" beside "string" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Listen for the middle: s-t-r or s-p-r?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR.M3_STR_DROP_R', 'ENGL.G3.LISTEN.T14_PRONUNCIATION_AND_VO.BLENDS_SPR_STR', 'Does not hear the r in str.', '{"question":"The teacher says \"stray\". Stray or stay?","wrong_answer":"stay","correct_answer":"stray"}'::jsonb, 'The last consonant of the cluster is lost.', 'Offer "stay" beside "stray" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stretch it: st-rrr-ay.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER.M3_AD_ADJECTIVE', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER', 'Uses an adjective to describe how something is done.', '{"question":"Wanjiku sings ...","wrong_answer":"beautiful","correct_answer":"beautifully"}'::jsonb, 'The describing word is not changed for the action.', 'Offer "beautiful" beside "beautifully" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How does she sing? Add -ly: beautifully.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER.M3_AD_GOOD', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER', 'Uses good for well.', '{"question":"Otieno plays the drum very ...","wrong_answer":"good","correct_answer":"well"}'::jsonb, 'Common Kenyan English.', 'Offer "good" beside "well" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Good describes a thing; well describes how you do it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER.M3_AD_SPELL', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER', 'Spells -ly words wrongly.', '{"question":"Write the adverb from careful.","wrong_answer":"carefuly","correct_answer":"carefully"}'::jsonb, 'The child adds -ly but drops a letter.', 'Offer "carefuly" beside "carefully" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Careful + ly = carefully, two l''s.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER.M3_AD_NOUN', 'ENGL.G3.LANGUA.T14_ADVERBS_OF_MANNER.ADVERBS_MANNER', 'Picks an adjective that describes a person as the adverb.', '{"question":"Which word tells how? \"The quick boy ran slowly.\"","wrong_answer":"quick","correct_answer":"slowly"}'::jsonb, 'Any describing word is taken as the adverb.', 'Offer "quick" beside "slowly" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The adverb tells how the action was done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS.M3_PRC_SKIP_PLAN', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS', 'Starts writing without planning.', '{"question":"What do we do first?","wrong_answer":"start writing the story","correct_answer":"plan: think and list ideas"}'::jsonb, 'Writing is seen as one step.', 'Offer "start writing the story" beside "plan: think and list ideas" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'First plan: who, where, what happens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS.M3_PRC_REVISE_EDIT', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS', 'Thinks revising and editing are the same.', '{"question":"At which step do we fix spelling?","wrong_answer":"revising","correct_answer":"editing"}'::jsonb, 'Both are about changing the writing.', 'Offer "revising" beside "editing" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Revise the ideas; edit the spelling and marks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS.M3_PRC_ORDER', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS', 'Puts the steps in the wrong order.', '{"question":"Order: draft, publish, plan, edit, revise","wrong_answer":"draft, plan, revise, edit, publish","correct_answer":"plan, draft, revise, edit, publish"}'::jsonb, 'The step names are new and their order is not linked to what they do.', 'Offer "draft, plan, revise, edit, publish" beside "plan, draft, revise, edit, publish" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Think, write, improve, fix, share.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS.M3_PRC_DRAFT_FINAL', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.WRITING_STEPS', 'Thinks the first draft is the finished work.', '{"question":"Is the first draft ready to hang on the wall?","wrong_answer":"yes","correct_answer":"no, it is revised and edited first"}'::jsonb, 'Work is usually handed in once.', 'Offer "yes" beside "no, it is revised and edited first" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A draft is a first try.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE.M3_NA_NO_END', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE', 'Stops the story with no ending.', '{"question":"Write a story about a talent show.","wrong_answer":"Ali went on stage. He started singing.","correct_answer":"... Everyone clapped and Ali won a prize."}'::jsonb, 'The child runs out of time or ideas.', 'Offer "Ali went on stage. He started singing." beside "... Everyone clapped and Ali won a prize." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'How did it end? Add one sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE.M3_NA_TENSE_MIX', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE', 'Mixes present and past.', '{"question":"Write a story about a talent show.","wrong_answer":"Ali goes on stage and he sang.","correct_answer":"Ali went on stage and he sang."}'::jsonb, 'Spoken stories slip between tenses.', 'Offer "Ali goes on stage and he sang." beside "Ali went on stage and he sang." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Stories are told in the past: went, sang.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE.M3_NA_NO_WHO', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE', 'Gives no names or setting.', '{"question":"Start your story.","wrong_answer":"He went there and did it.","correct_answer":"On Friday, Ali went to the school hall."}'::jsonb, 'The child knows who and where and forgets to tell the reader.', 'Offer "He went there and did it." beside "On Friday, Ali went to the school hall." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Who, where and when in the first sentence.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE.M3_NA_DAY_LIST', 'ENGL.G3.WRITIN.T14_GUIDED_WRITING.SHORT_NARRATIVE', 'Lists the day''s events with no problem.', '{"question":"Write a story about a day you showed your talent.","wrong_answer":"I woke up. I ate. I went to school. I slept.","correct_answer":"At the talent show my drum broke, but I sang instead and won."}'::jsonb, 'A story is seen as a list of what happened.', 'Offer "I woke up. I ate. I went to school. I slept." beside "At the talent show my drum broke, but I sang instead and won." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A story needs a problem and how it was solved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE.M3_QU_K_ONLY', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE', 'Hears qu as k, missing the w sound.', '{"question":"The teacher says \"queen\". Queen or keen?","wrong_answer":"keen","correct_answer":"queen"}'::jsonb, 'The child knows q as /k/ and does not hear the w after it.', 'Offer "keen" beside "queen" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Qu says k-w: round the lips, queen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE.M3_SCR_STR', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE', 'Hears scr as str.', '{"question":"The teacher says \"scrap\". Scrap or strap?","wrong_answer":"strap","correct_answer":"scrap"}'::jsonb, 'The middle sound of the cluster is missed.', 'Offer "strap" beside "scrap" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Scr has k in the middle: s-k-r.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE.M3_SCR_EXTRA_VOWELS', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE', 'Hears vowels between s, c and r.', '{"question":"Clap the beats in \"scrub\".","wrong_answer":"3 (si-ku-rub)","correct_answer":"1"}'::jsonb, 'A vowel after every consonant.', 'Offer "3 (si-ku-rub)" beside "1" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Scr glued: scrub, one clap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE.M3_QUEUE_RHYME', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.BLENDS_SCR_QUE', 'Reads the vowels of queue one by one and cannot match its sound.', '{"question":"Which word rhymes with \"queue\": few, quick, quiet?","wrong_answer":"quick","correct_answer":"few"}'::jsonb, 'Queue is spelt with four vowels after q; the child sounds the letters, not the word.', 'Offer "quick" beside "few" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Queue says kyoo, like the letter name Q.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING.M3_UW_ONE_WORD', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING', 'Answers with one word and stops.', '{"question":"Partner: \"What do you do at home on Saturday?\"","wrong_answer":"Sweep.","correct_answer":"I sweep the house and fetch water."}'::jsonb, 'One word answers the question, so the child stops there.', 'Offer "Sweep." beside "I sweep the house and fetch water." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Answer in a full sentence and add one more thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING.M3_UW_BORROW_LEND', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING', 'Uses borrow for lend.', '{"question":"Ask a friend for a pencil.","wrong_answer":"Borrow me your pencil.","correct_answer":"Please lend me your pencil."}'::jsonb, 'Kiswahili has one word (azima) for both, carried into English.', 'Offer "Borrow me your pencil." beside "Please lend me your pencil." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'You borrow from someone; someone lends to you.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING.M3_UW_OPEN_LIGHT', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING', 'Translates word for word from Kiswahili.', '{"question":"Ask your sister to put the light on.","wrong_answer":"Open the light.","correct_answer":"Please switch on the light."}'::jsonb, 'Fungua taa is said word for word in English.', 'Offer "Open the light." beside "Please switch on the light." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'We switch on lights and open doors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING.M3_UW_ECHO', 'ENGL.G3.LISTEN.T15_PRONUNCIATION_AND_VO.USE_WORDS_SPEAKING', 'Repeats the question instead of answering it.', '{"question":"Teacher: \"What is your talent?\"","wrong_answer":"What is my talent.","correct_answer":"My talent is singing."}'::jsonb, 'The child repeats the words to buy time.', 'Offer "What is my talent." beside "My talent is singing." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Start with My ... is ...', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS.M3_DS_HAPPY_WORD', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS', 'Uses a happy interjection for displeasure.', '{"question":"The rain spoilt our clean clothes. \"...\" said Mama.","wrong_answer":"Hurray!","correct_answer":"Oh no!"}'::jsonb, 'Interjections are learnt as a list without their feelings.', 'Offer "Hurray!" beside "Oh no!" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Hurray is for joy; Oh no is for bad news.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS.M3_DS_PAIN_DISGUST', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS', 'Uses ouch for disgust.', '{"question":"The milk has gone bad and smells. \"...!\"","wrong_answer":"Ouch","correct_answer":"Yuck"}'::jsonb, 'Ouch and yuck are both unhappy words.', 'Offer "Ouch" beside "Yuck" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ouch is for pain; yuck is for something nasty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS.M3_DS_NO_MARK', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS', 'Leaves out the exclamation mark.', '{"question":"Write: Ugh I missed the bus","wrong_answer":"Ugh I missed the bus.","correct_answer":"Ugh! I missed the bus."}'::jsonb, 'The child writes the interjection as part of the sentence.', 'Offer "Ugh I missed the bus." beside "Ugh! I missed the bus." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A strong feeling: an exclamation mark after it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS.M3_DS_HOME_WORD', 'ENGL.G3.LANGUA.T15_INTERJECTIONS_OF_DIS.DISPLEASURE_WORDS', 'Uses a home-language or Sheng exclamation in English writing.', '{"question":"Write how Ali felt when he lost his savings.","wrong_answer":"Wueh! I lost my money.","correct_answer":"Oh no! I lost my money."}'::jsonb, 'Everyday Kenyan exclamations (wueh, aii) are used at home and carried into writing.', 'Offer "Wueh! I lost my money." beside "Oh no! I lost my money." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'In English writing use Oh no, Ugh, Alas.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES.M3_FA_OPINION', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES', 'Takes an opinion as a fact.', '{"question":"Which is a fact?","wrong_answer":"Trees are the most beautiful plants.","correct_answer":"Trees give us shade."}'::jsonb, 'Something the child agrees with feels true.', 'Offer "Trees are the most beautiful plants." beside "Trees give us shade." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Can everyone check it? Then it is a fact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES.M3_FA_STORY', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES', 'Takes a story sentence as a fact.', '{"question":"Which is a fact?","wrong_answer":"One day a tree talked to a bird.","correct_answer":"Birds build nests in trees."}'::jsonb, 'Any sentence in a book seems true.', 'Offer "One day a tree talked to a bird." beside "Birds build nests in trees." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Facts are true in real life.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES.M3_FA_NO_I_THINK', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES', 'Thinks any sentence without I think is a fact.', '{"question":"Is \"Litter is ugly\" a fact?","wrong_answer":"yes","correct_answer":"no, it is an opinion"}'::jsonb, 'The child has learnt that opinions start with I think.', 'Offer "yes" beside "no, it is an opinion" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Words like ugly, best and nice show opinions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES.M3_FA_FALSE', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACT_SENTENCES', 'Takes a false statement as a fact because it sounds like one.', '{"question":"Which is a fact?","wrong_answer":"Trees grow in one day.","correct_answer":"Trees need water to grow."}'::jsonb, 'Fact is taken to mean a sentence that sounds like a fact.', 'Offer "Trees grow in one day." beside "Trees need water to grow." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'A fact must be true.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS.M3_OF_SKIP', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS', 'Leaves out a step.', '{"question":"Steps to plant a tree: dig a hole, ..., cover the roots, water it.","wrong_answer":"dig a hole, cover the roots, water it","correct_answer":"dig a hole, put in the seedling, cover the roots, water it"}'::jsonb, 'The child does not check that each step can follow the last.', 'Offer "dig a hole, cover the roots, water it" beside "dig a hole, put in the seedling, cover the roots, water it" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Can you cover the roots before the seedling is in?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS.M3_OF_LAST_FIRST', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS', 'Puts the last step first.', '{"question":"First step to plant a tree?","wrong_answer":"water it","correct_answer":"dig a hole"}'::jsonb, 'The best-known step comes to mind first.', 'Offer "water it" beside "dig a hole" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'What must happen before anything else?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS.M3_OF_INTEREST', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS', 'Orders by what is most interesting.', '{"question":"Order: collect litter, put on gloves, throw it in the bin.","wrong_answer":"throw it in the bin, collect litter, put on gloves","correct_answer":"put on gloves, collect litter, throw it in the bin"}'::jsonb, 'Interest is used in place of order.', 'Offer "throw it in the bin, collect litter, put on gloves" beside "put on gloves, collect litter, throw it in the bin" in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Ask what has to be done first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS.M3_OF_TIME_WORDS', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.ORDER_FACTS', 'Ignores first, next and finally.', '{"question":"Which comes last: \"First, dig.\" \"Finally, water.\" \"Next, plant.\"","wrong_answer":"Next, plant.","correct_answer":"Finally, water."}'::jsonb, 'The time words are not read.', 'Offer "Next, plant." beside "Finally, water." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Finally means last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH.M3_FP_STORY', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH', 'Writes a story instead of facts.', '{"question":"Write a paragraph of facts about planting trees.","wrong_answer":"One day I planted a tree and it talked.","correct_answer":"Trees are planted in the rainy season. First we dig a hole ..."}'::jsonb, 'Most writing so far has been stories.', 'Offer "One day I planted a tree and it talked." beside "Trees are planted in the rainy season. First we dig a hole ..." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Facts, no characters: tell how it is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH.M3_FP_OPINION', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH', 'Fills the paragraph with opinions.', '{"question":"Write facts about keeping the environment clean.","wrong_answer":"Litter is ugly. I hate litter.","correct_answer":"Litter blocks drains. We put it in bins."}'::jsonb, 'Feelings come first.', 'Offer "Litter is ugly. I hate litter." beside "Litter blocks drains. We put it in bins." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Keep only what can be checked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH.M3_FP_NO_ORDER', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH', 'Writes the facts in no order.', '{"question":"Write how to plant a tree.","wrong_answer":"Water it. Dig a hole. Cover it.","correct_answer":"First dig a hole. Next plant the seedling. Then cover the roots. Finally water it."}'::jsonb, 'Facts are written as they come to mind.', 'Offer "Water it. Dig a hole. Cover it." beside "First dig a hole. Next plant the seedling. Then cover the roots. Finally water it." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'Number the steps first, then write.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH.M3_FP_NO_OPENING', 'ENGL.G3.WRITIN.T15_GUIDED_WRITING_FACTU.FACTUAL_PARAGRAPH', 'Starts with a detail, not what the paragraph is about.', '{"question":"Begin a paragraph about saving water.","wrong_answer":"Turn the tap off.","correct_answer":"We can save water at home in many ways."}'::jsonb, 'The child goes straight to the first fact.', 'Offer "Turn the tap off." beside "We can save water at home in many ways." in a fresh sentence or text and ask again; picking it again shows the error is still there.', 'The first sentence tells what the paragraph is about.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
